package cmd

import (
	"flag"
	"fmt"
	"os"
	"strings"
)

// Command is a simple command implementation
type Command struct {
	Use             string
	Short           string
	Long            string
	Example         string
	Aliases         []string
	GroupedCommands []string
	RunE            func(cmd *Command, args []string) error

	flags        *flag.FlagSet
	subcommands  []*Command
	parent       *Command
}

func (c *Command) Flags() *flag.FlagSet {
	if c.flags == nil {
		c.flags = flag.NewFlagSet(c.Use, flag.ContinueOnError)
		c.flags.SetOutput(os.Stderr)
	}
	return c.flags
}

func (c *Command) AddCommand(sub *Command) {
	sub.parent = c
	c.subcommands = append(c.subcommands, sub)
}

func (c *Command) Name() string {
	parts := strings.SplitN(c.Use, " ", 2)
	return parts[0]
}

func (c *Command) Execute() error {
	return c.executeArgs(os.Args[1:])
}

func (c *Command) executeArgs(args []string) error {
	// Check for help flags
	for _, a := range args {
		if a == "-h" || a == "--help" {
			c.Usage()
			return nil
		}
	}

	// Check for version
	for _, a := range args {
		if a == "-v" || a == "--version" {
			fmt.Fprintf(os.Stdout, "\ndep-tree version v0.23.4\n")
			return nil
		}
	}

	// Try to find subcommand
	if len(args) > 0 {
		for _, sub := range c.subcommands {
			subName := sub.Name()
			if args[0] == subName {
				return sub.runWithArgs(args[1:])
			}
			for _, alias := range sub.Aliases {
				if args[0] == alias {
					return sub.runWithArgs(args[1:])
				}
			}
		}
	}

	// Run current command
	if c.RunE == nil {
		c.Usage()
		return nil
	}

	// Parse global flags
	if c.flags != nil {
		if err := c.flags.Parse(args); err != nil {
			if err == flag.ErrHelp {
				return nil
			}
			return err
		}
		args = c.flags.Args()
	}

	return c.RunE(c, args)
}

func (c *Command) runWithArgs(args []string) error {
	// Check for help
	for _, a := range args {
		if a == "-h" || a == "--help" {
			c.Usage()
			return nil
		}
	}

	// Parse flags (inheriting parent flags)
	allFlags := flag.NewFlagSet(c.Name(), flag.ContinueOnError)
	allFlags.SetOutput(os.Stderr)

	// Add parent (global) flags
	if c.parent != nil && c.parent.flags != nil {
		c.parent.flags.VisitAll(func(f *flag.Flag) {
			allFlags.Var(f.Value, f.Name, f.Usage)
		})
	}

	// Add command-specific flags
	if c.flags != nil {
		c.flags.VisitAll(func(f *flag.Flag) {
			allFlags.Var(f.Value, f.Name, f.Usage)
		})
	}

	if err := allFlags.Parse(args); err != nil {
		if err == flag.ErrHelp {
			return nil
		}
		return err
	}

	remaining := allFlags.Args()

	if c.RunE == nil {
		c.Usage()
		return nil
	}

	return c.RunE(c, remaining)
}

func (c *Command) Usage() {
	out := os.Stdout

	if c.Long != "" {
		fmt.Fprintln(out, c.Long)
	} else if c.Short != "" {
		fmt.Fprintf(out, "%s\n\n", c.Short)
	}

	fmt.Fprintf(out, "Usage:\n  %s\n", c.Use)

	if c.Example != "" {
		fmt.Fprintf(out, "\nExamples:\n%s\n", c.Example)
	}

	if len(c.subcommands) > 0 {
		fmt.Fprintln(out)
		for _, sub := range c.subcommands {
			fmt.Fprintf(out, "  %-12s %s\n", sub.Name(), sub.Short)
		}
	}

	fmt.Fprintln(out, "\nFlags:")
	if c.flags != nil {
		c.flags.VisitAll(func(f *flag.Flag) {
			fmt.Fprintf(out, "  --%s %s\n", f.Name, f.Usage)
		})
	}
	fmt.Fprintln(out, "  -h, --help  help for "+c.Name())
}
