package main

import (
	"path/filepath"
	"sort"
)

// Node represents a file in the dependency graph
type Node struct {
	ID       string   // Absolute path
	RelPath  string   // Path relative to the project root
	Deps     []string // Absolute paths of dependencies
	Errors   []string // Parse errors
	LOC      int      // Lines of code
}

// Graph represents the full dependency graph
type Graph struct {
	Nodes       map[string]*Node // key = absolute path
	Root        string           // Absolute path of root directory
	Entrypoints []string         // Absolute paths of entrypoints
}

func newGraph(root string) *Graph {
	return &Graph{
		Nodes: make(map[string]*Node),
		Root:  root,
	}
}

func (g *Graph) addNode(absPath string) *Node {
	if n, ok := g.Nodes[absPath]; ok {
		return n
	}
	relPath, err := filepath.Rel(g.Root, absPath)
	if err != nil {
		relPath = absPath
	}
	n := &Node{
		ID:      absPath,
		RelPath: relPath,
	}
	g.Nodes[absPath] = n
	return n
}

// TreeNode represents a node in the dependency tree
type TreeNode struct {
	Path     string
	Children []*TreeNode // deduplicated children
	Parents  []*TreeNode // all parents
	Errors   []string
}

// BuildTree creates the dependency tree from the graph
// It deduplicates nodes that appear multiple times
func BuildTree(g *Graph, entrypoint string, gf *GlobalFlags) (*TreeResult, error) {
	result := &TreeResult{
		CircularDeps: [][]string{},
		Errors:       make(map[string][]string),
	}

	// BFS traversal to find all nodes and build tree
	visited := make(map[string]bool)
	nodeMap := make(map[string]*treeBuilderNode)

	var buildOrder []string
	queue := []string{entrypoint}

	// Find cycles
	cycles := findCycles(g, entrypoint)
	cycleSet := make(map[string]bool)
	for _, cycle := range cycles {
		for i := 0; i < len(cycle)-1; i++ {
			key := cycle[i] + "||" + cycle[i+1]
			cycleSet[key] = true
		}
		result.CircularDeps = append(result.CircularDeps, cycle)
	}

	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]

		if visited[cur] {
			continue
		}
		visited[cur] = true
		buildOrder = append(buildOrder, cur)

		node := g.Nodes[cur]
		if node == nil {
			continue
		}

		tbn := getOrCreate(nodeMap, cur)
		if len(node.Errors) > 0 {
			result.Errors[node.RelPath] = node.Errors
		}

		// Sort children alphabetically for consistent ordering
		children := make([]string, len(node.Deps))
		copy(children, node.Deps)
		sort.Strings(children)

		for _, dep := range children {
			childTbn := getOrCreate(nodeMap, dep)
			childTbn.parents = append(childTbn.parents, cur)
			tbn.children = append(tbn.children, dep)
			if !visited[dep] {
				queue = append(queue, dep)
			}
		}
	}
	_ = buildOrder
	_ = cycleSet

	result.Tree = buildTreeJSON(g, entrypoint, nodeMap)
	return result, nil
}

type treeBuilderNode struct {
	path     string
	children []string
	parents  []string
}

func getOrCreate(m map[string]*treeBuilderNode, path string) *treeBuilderNode {
	if n, ok := m[path]; ok {
		return n
	}
	n := &treeBuilderNode{path: path}
	m[path] = n
	return n
}

func findCycles(g *Graph, start string) [][]string {
	var cycles [][]string
	visited := make(map[string]bool)
	path := []string{}
	pathSet := make(map[string]int) // value = index in path

	var dfs func(node string)
	dfs = func(node string) {
		if idx, inPath := pathSet[node]; inPath {
			// Found a cycle
			cycle := make([]string, len(path)-idx+1)
