package main

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

// FileNode represents a file in the dependency graph
type FileNode struct {
	AbsPath  string
	RelPath  string   // relative to project root
	Deps     []string // absolute paths of direct dependencies
	Errors   []string // parse errors
	LOC      int      // lines of code (number of newlines)
	Size     int      // display size metric
}

// Graph is the complete dependency graph
type Graph struct {
	Root   string                // project root directory  
	Nodes  map[string]*FileNode  // keyed by absolute path
	Order  []string              // BFS order from entrypoints
}

func newGraph(root string) *Graph {
	return &Graph{
		Root:  root,
		Nodes: make(map[string]*FileNode),
	}
}

func (g *Graph) addOrGetNode(absPath string) *FileNode {
	if n, ok := g.Nodes[absPath]; ok {
		return n
	}
	rel, err := filepath.Rel(g.Root, absPath)
	if err != nil {
		rel = absPath
	}
	n := &FileNode{
		AbsPath: absPath,
		RelPath: rel,
	}
	g.Nodes[absPath] = n
	return n
}

// Build constructs the dependency graph starting from entrypoints
func (g *Graph) Build(entrypoints []string, flags *Flags, filters []FileFilter) error {
	visited := make(map[string]bool)
	queue := make([]string, 0, len(entrypoints))
	queue = append(queue, entrypoints...)

	total := 0
	processed := 0

	// First pass: count total files (approximate)
	for _, ep := range entrypoints {
		if _, err := os.Stat(ep); err == nil {
			total++
		}
	}

	printProgress(processed, total, "Loading Files...")

	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]

		if visited[cur] {
			continue
		}
		visited[cur] = true
		processed++
		g.Order = append(g.Order, cur)

		node := g.addOrGetNode(cur)

		// Check if file should be filtered
		if shouldFilter(node.RelPath, filters) {
			continue
		}

		// Parse the file to find dependencies
		deps, errors := parseFileDeps(cur, g.Root, flags)
		node.Errors = errors

		// Apply filters to deps
		var filteredDeps []string
		for _, dep := range deps {
			depNode := g.addOrGetNode(dep)
			if !shouldFilter(depNode.RelPath, filters) {
				filteredDeps = append(filteredDeps, dep)
				if !visited[dep] {
					queue = append(queue, dep)
					total++
				}
			}
		}
		node.Deps = filteredDeps

		// Count LOC
		node.LOC, node.Size = countLOC(cur)

		printProgress(processed, total, "Loading Files...")
	}

	printProgress(processed, total, "Finished loading")
	printProgress(processed, total, "Finished loading")

	return nil
}

// FileFilter determines which files to include/exclude
type FileFilter struct {
	Pattern string
	Include bool // true = only include, false = exclude
}

func shouldFilter(relPath string, filters []FileFilter) bool {
	for _, f := range filters {
		matched, _ := globMatch(f.Pattern, relPath)
		if f.Include {
			// "only" filter: must match to be included
			if !matched {
				return true // filter out (not matched)
			}
		} else {
			// "exclude" filter: must NOT match to be included
			if matched {
				return true // filter out (matched)
			}
		}
	}
	return false
}

func countLOC(path string) (loc int, size int) {
	content, err := os.ReadFile(path)
	if err != nil {
		return 0, 0
	}
	for _, b := range content {
		if b == '\n' {
			loc++
		}
	}
	// size is same as loc for now
	size = loc
	return
}

var progressSpinners = []string{"⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"}
var spinnerIdx int

func printProgress(processed, total int, msg string) {
	spinner := progressSpinners[spinnerIdx%len(progressSpinners)]
	spinnerIdx++

	var line string
	if total == 0 {
		line = fmt.Sprintf("%s  (0 it/hr) [0s] ", spinner)
	} else {
		line = fmt.Sprintf("%s (%d/%d) %s (%d it/s) [0s] ", spinner, processed, total, msg, processed*1000)
	}

	clearLine := strings.Repeat(" ", len([]rune(line))+2)
	fmt.Fprintf(os.Stderr, "\r%s\r%s\r\n%s\r", line, clearLine, clearLine)
}

// TreeResult is the JSON output of the tree command
type TreeResult struct {
	Tree         interface{}         `json:"tree"`
	CircularDeps [][]string          `json:"circularDependencies"`
	Errors       map[string][]string `json:"errors"`
}

// BuildTree creates the tree result from the graph
func BuildTree(g *Graph, entrypoint string) *TreeResult {
	result := &TreeResult{
		CircularDeps: [][]string{},
		Errors:       make(map[string][]string),
	}

	// Collect errors
	for _, node := range g.Nodes {
		if len(node.Errors) > 0 {
			result.Errors[node.RelPath] = node.Errors
		}
	}

	// Find cycles
	cycles := findCycles(g, entrypoint)
	result.CircularDeps = append(result.CircularDeps, cycles...)

	// Build tree structure
	visited := make(map[string]bool)
	result.Tree = buildTreeMap(g, entrypoint, visited)

	return result
}

// buildTreeMap builds the deduplicated tree as an ordered map
func buildTreeMap(g *Graph, root string, visited map[string]bool) interface{} {
	node := g.Nodes[root]
	if node == nil {
