		// Count LOC
		node.LOC, node.Size = countLOC(cur)

		printProgress(processed, total, "Loading Files...")
	}

	printProgress(processed, total, "Finished loading")
	printProgress(processed, total, "Finished loading")

	return nil
}

// FileFilter determines which files to include/exclude
type FileFilter struct {
	Pattern string
	Include bool // true = only include, false = exclude
}

func shouldFilter(relPath string, filters []FileFilter) bool {
	for _, f := range filters {
		matched, _ := globMatch(f.Pattern, relPath)
		if f.Include {
			// "only" filter: must match to be included
			if !matched {
				return true // filter out (not matched)
			}
		} else {
			// "exclude" filter: must NOT match to be included
			if matched {
				return true // filter out (matched)
			}
		}
	}
	return false
}

func countLOC(path string) (loc int, size int) {
	content, err := os.ReadFile(path)
	if err != nil {
		return 0, 0
	}
	for _, b := range content {
		if b == '\n' {
			loc++
		}
	}
	// size is same as loc for now
	size = loc
	return
}

var progressSpinners = []string{"⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"}
var spinnerIdx int

func printProgress(processed, total int, msg string) {
	spinner := progressSpinners[spinnerIdx%len(progressSpinners)]
	spinnerIdx++

	var line string
	if total == 0 {
		line = fmt.Sprintf("%s  (0 it/hr) [0s] ", spinner)
	} else {
		line = fmt.Sprintf("%s (%d/%d) %s (%d it/s) [0s] ", spinner, processed, total, msg, processed*1000)
	}

	clearLine := strings.Repeat(" ", len([]rune(line))+2)
	fmt.Fprintf(os.Stderr, "\r%s\r%s\r\n%s\r", line, clearLine, clearLine)
}

// TreeResult is the JSON output of the tree command
type TreeResult struct {
	Tree         interface{}         `json:"tree"`
	CircularDeps [][]string          `json:"circularDependencies"`
	Errors       map[string][]string `json:"errors"`
}

// BuildTree creates the tree result from the graph
func BuildTree(g *Graph, entrypoint string) *TreeResult {
	result := &TreeResult{
		CircularDeps: [][]string{},
		Errors:       make(map[string][]string),
	}

	// Collect errors
	for _, node := range g.Nodes {
		if len(node.Errors) > 0 {
			result.Errors[node.RelPath] = node.Errors
		}
	}

	// Find cycles
	cycles := findCycles(g, entrypoint)
	result.CircularDeps = append(result.CircularDeps, cycles...)

	// Build tree structure
	visited := make(map[string]bool)
	result.Tree = buildTreeMap(g, entrypoint, visited)

	return result
}

// buildTreeMap builds the deduplicated tree as an ordered map
func buildTreeMap(g *Graph, root string, visited map[string]bool) interface{} {
	node := g.Nodes[root]
	if node == nil {
		return nil
	}

	outer := orderedMap{}
	outer[node.RelPath] = buildSubtree(g, root, visited)
	return outer
}

func buildSubtree(g *Graph, path string, visited map[string]bool) interface{} {
	if visited[path] {
		return nil
	}

	node := g.Nodes[path]
	if node == nil {
		return nil
	}

	if len(node.Deps) == 0 {
		visited[path] = true
		return nil
	}

	visited[path] = true

	// Sort deps alphabetically
	deps := make([]string, len(node.Deps))
	copy(deps, node.Deps)
	sort.Strings(deps)

	result := orderedMap{}
	for _, dep := range deps {
		depNode := g.Nodes[dep]
		if depNode == nil {
			continue
		}
		result[depNode.RelPath] = buildSubtree(g, dep, visited)
	}

	return result
}

// findCycles finds all cycles in the graph reachable from start
func findCycles(g *Graph, start string) [][]string {
	var cycles [][]string
	inStack := make(map[string]int) // path -> index in current DFS path
	path := []string{}
	visited := make(map[string]bool)

	var dfs func(node string)
	dfs = func(node string) {
		if idx, inPath := inStack[node]; inPath {
			// Found a cycle - extract it
			cycleNodes := path[idx:]
			cycle := make([]string, len(cycleNodes)+1)
			for i, p := range cycleNodes {
				n := g.Nodes[p]
				if n != nil {
					cycle[i] = n.RelPath
				} else {
					cycle[i] = p
				}
			}
			// Add the start of cycle to end
			n := g.Nodes[node]
			if n != nil {
				cycle[len(cycle)-1] = n.RelPath
			} else {
				cycle[len(cycle)-1] = node
			}
			cycles = append(cycles, cycle)
			return
		}
		if visited[node] {
			return
		}

		visited[node] = true
		inStack[node] = len(path)
		path = append(path, node)

		gNode := g.Nodes[node]
		if gNode != nil {
			// Sort deps for consistent cycle detection
			deps := make([]string, len(gNode.Deps))
			copy(deps, gNode.Deps)
			sort.Strings(deps)
			for _, dep := range deps {
				dfs(dep)
			}
		}

		path = path[:len(path)-1]
		delete(inStack, node)
	}

	dfs(start)
	return cycles
}

// buildBFSOrder returns all nodes in BFS order from entrypoint
// with deduplication (each node appears only once)
func buildBFSOrder(g *Graph, entrypoint string) []string {
	visited := make(map[string]bool)
	var order []string
	queue := []string{entrypoint}

	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]

		if visited[cur] {
			continue
		}
		visited[cur] = true
		order = append(order, cur)

		node := g.Nodes[cur]
		if node == nil {
			continue
		}

		// Add children in sorted order
		deps := make([]string, len(node.Deps))
		copy(deps, node.Deps)
		sort.Strings(deps)

		for _, dep := range deps {
			if !visited[dep] {
				queue = append(queue, dep)
			}
		}
	}

	return order
}
