package main

import (
	"path/filepath"
	"strings"
)

// globMatch matches a pattern against a path, supporting ** glob
func globMatch(pattern, path string) (bool, error) {
	// Normalize path separators
	pattern = filepath.ToSlash(pattern)
	path = filepath.ToSlash(path)

	return matchGlob(pattern, path), nil
}

// matchGlob implements ** globbing
func matchGlob(pattern, path string) bool {
	// Split into parts
	pp := strings.Split(pattern, "/")
	fp := strings.Split(path, "/")

	return matchParts(pp, fp)
}

func matchParts(pp, fp []string) bool {
	for len(pp) > 0 && len(fp) > 0 {
		p := pp[0]
		f := fp[0]

		if p == "**" {
			// ** matches zero or more path components
			pp = pp[1:]
			if len(pp) == 0 {
				return true // ** at end matches everything
			}
			// Try matching the remaining pattern against every suffix of fp
			for i := 0; i <= len(fp); i++ {
				if matchParts(pp, fp[i:]) {
					return true
				}
			}
			return false
		}

		matched, err := filepath.Match(p, f)
		if err != nil || !matched {
			return false
		}
		pp = pp[1:]
		fp = fp[1:]
	}

	// Skip trailing ** in pattern
	for len(pp) > 0 && pp[0] == "**" {
		pp = pp[1:]
	}

	return len(pp) == 0 && len(fp) == 0
}

// globMatchFiles returns all files matching a pattern relative to a base dir
func globMatchFiles(pattern, baseDir string) ([]string, error) {
	// If pattern doesn't contain **, use standard Glob
	if !strings.Contains(pattern, "**") {
		matches, err := filepath.Glob(filepath.Join(baseDir, pattern))
		if err != nil {
			return nil, err
		}
		return matches, nil
	}

	// Walk directory and match files
	var results []string
	err := walkDirForGlob(baseDir, baseDir, pattern, &results)
	return results, err
}

func walkDirForGlob(baseDir, currentDir, pattern string, results *[]string) error {
	entries, err := readDir(currentDir)
	if err != nil {
		return nil // ignore errors
	}

	for _, entry := range entries {
		fullPath := filepath.Join(currentDir, entry.Name())
		relPath, _ := filepath.Rel(baseDir, fullPath)
		relPath = filepath.ToSlash(relPath)

		if entry.IsDir() {
			walkDirForGlob(baseDir, fullPath, pattern, results)
		} else {
			if matchGlob(pattern, relPath) {
				*results = append(*results, fullPath)
			}
		}
	}
	return nil
}
