package main

import (
	"encoding/json"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
)

var (
	// Match import/export statements with string literals
	jsImportRe = regexp.MustCompile(`(?:import|export)\s+(?:[^'"]*?\s+from\s+)?(['"])(\.\.?/[^'"]*|[^\.'"@][^'"]*)\1`)
	// Match require() calls
	jsRequireRe = regexp.MustCompile(`require\s*\(\s*(['"])(\.\.?/[^'"]*)\1\s*\)`)
	// Match dynamic imports
	jsDynamicImportRe = regexp.MustCompile(`import\s*\(\s*(['"])(\.\.?/[^'"]*)\1\s*\)`)
	// Export from
	jsExportFromRe = regexp.MustCompile(`export\s+(?:\*\s+from|{[^}]*}\s+from)\s+(['"])(\.\.?/[^'"]*)\1`)
)

// parseJSImports parses JS/TS file and returns imported local file paths
func parseJSImports(filePath, projectRoot string, flags *Flags) ([]string, []string) {
	content, err := os.ReadFile(filePath)
	if err != nil {
		return nil, []string{err.Error()}
	}

	dir := filepath.Dir(filePath)
	src := string(content)

	// Remove comments and strings to avoid false positives
	cleaned := removeComments(src)

	var imports []string
	seen := make(map[string]bool)
	var errors []string

	// Find all import/export specifiers
	importPaths := extractJSImports(cleaned)

	for _, importPath := range importPaths {
		// Skip non-relative imports if not workspace
		if !strings.HasPrefix(importPath, ".") {
			// Check if it's a workspace-mapped path via tsconfig
			if flags.JsTsconfigPaths {
				resolved := resolveTSConfigPath(importPath, projectRoot, dir)
				if resolved != "" {
					importPath = resolved
				} else if flags.JsWorkspaces {
					resolved = resolveWorkspacePath(importPath, projectRoot, dir)
					if resolved != "" {
						importPath = resolved
					} else {
						continue
					}
				} else {
					continue
				}
			} else if flags.JsWorkspaces {
				resolved := resolveWorkspacePath(importPath, projectRoot, dir)
				if resolved != "" {
					importPath = resolved
				} else {
					continue
				}
			} else {
				continue
			}
		}

		// Resolve the import path to an actual file
		resolved, err := resolveJSImport(dir, importPath, projectRoot)
		if err != nil {
			errors = append(errors, err.Error())
			continue
		}
		if resolved == "" {
			continue
		}

		if !seen[resolved] {
			seen[resolved] = true
			imports = append(imports, resolved)
		}
	}

	sort.Strings(imports)
	return imports, errors
}

// extractJSImports extracts all import paths from JS/TS source
func extractJSImports(src string) []string {
	seen := make(map[string]bool)
	var paths []string

	addPath := func(p string) {
		if !seen[p] {
			seen[p] = true
			paths = append(paths, p)
		}
	}

	// Various import patterns
	// import X from 'path'
	// import { X } from 'path'  
	// import * as X from 'path'
	// import 'path'
	// export { X } from 'path'
	// export * from 'path'
	// const x = require('path')
	// const x = await import('path')

	// Use a simple state machine to find all import/export/require paths
	i := 0
	for i < len(src) {
		// Look for import, export, require keywords
		if i+6 <= len(src) && src[i:i+6] == "import" && (i == 0 || !isIdentChar(src[i-1])) && (i+6 >= len(src) || !isIdentChar(src[i+6])) {
			// import statement
			j := i + 6
			j = skipWhitespace(src, j)
			if j < len(src) && (src[j] == '(' ) {
				// Dynamic import: import('path')
				j++ // skip (
				j = skipWhitespace(src, j)
				if j < len(src) && (src[j] == '\'' || src[j] == '"' || src[j] == '`') {
					path, end := extractString(src, j)
					if end > j {
						addPath(path)
						i = end
						continue
					}
				}
			} else {
				// Static import: find 'from' and string
				path, end := findFromString(src, j)
				if end > j && path != "" {
					addPath(path)
					i = end
					continue
				}
				// import 'path' (side effect)
				if j < len(src) && (src[j] == '\'' || src[j] == '"' || src[j] == '`') {
					path, end := extractString(src, j)
					if end > j {
						addPath(path)
						i = end
						continue
					}
				}
			}
		}

		if i+6 <= len(src) && src[i:i+6] == "export" && (i == 0 || !isIdentChar(src[i-1])) && (i+6 >= len(src) || !isIdentChar(src[i+6])) {
			// export statement - look for 'from'
			j := i + 6
			path, end := findFromString(src, j)
			if end > j && path != "" {
				addPath(path)
				i = end
				continue
			}
		}

		if i+7 <= len(src) && src[i:i+7] == "require" && (i == 0 || !isIdentChar(src[i-1])) && (i+7 < len(src) && src[i+7] == '(') {
			// require('path')
			j := i + 8 // skip require(
			j = skipWhitespace(src, j)
			if j < len(src) && (src[j] == '\'' || src[j] == '"' || src[j] == '`') {
				path, end := extractString(src, j)
				if end > j {
					addPath(path)
					i = end
					continue
				}
			}
		}

		i++
	}

	return paths
}

func isIdentChar(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_' || c == '$'
}

func skipWhitespace(src string, i int) int {
	for i < len(src) && (src[i] == ' ' || src[i] == '\t' || src[i] == '\n' || src[i] == '\r') {
		i++
	}
	return i
}

// findFromString looks for the 'from' keyword followed by a string
func findFromString(src string, start int) (string, int) {
	i := start
	// Scan for 'from' keyword within a reasonable range
	limit := i + 200 // max chars to scan
	if limit > len(src) {
		limit = len(src)
	}

	for i < limit {
		i = skipWhitespace(src, i)
		if i >= limit {
			break
		}

		// Check for 'from' keyword
		if i+4 <= len(src) && src[i:i+4] == "from" && (i == 0 || !isIdentChar(src[i-1])) && (i+4 >= len(src) || !isIdentChar(src[i+4])) {
			j := i + 4
			j = skipWhitespace(src, j)
			if j < len(src) && (src[j] == '\'' || src[j] == '"' || src[j] == '`') {
				path, end := extractString(src, j)
				if end > j {
					return path, end
				}
			}
			return "", i
		}

		// Skip over identifiers, operators, etc.
		if isIdentChar(src[i]) {
			for i < limit && isIdentChar(src[i]) {
				i++
			}
		} else if src[i] == '\'' || src[i] == '"' || src[i] == '`' {
			// Skip string
			_, end := extractString(src, i)
			i = end
		} else if src[i] == '{' {
			// Skip to matching }
			depth := 1
			i++
			for i < limit && depth > 0 {
				if src[i] == '{' {
					depth++
				} else if src[i] == '}' {
					depth--
				}
				i++
			}
		} else if src[i] == '*' || src[i] == ',' || src[i] == ' ' || src[i] == '\t' {
			i++
		} else {
			break
		}
	}
	return "", start
}

// extractString extracts a quoted string starting at position i
func extractString(src string, i int) (string, int) {
	if i >= len(src) {
		return "", i
	}
	quote := src[i]
	if quote != '\'' && quote != '"' && quote != '`' {
		return "", i
	}

	i++
	var result strings.Builder
	for i < len(src) {
		c := src[i]
		if c == '\\' {
			i++
			if i < len(src) {
				result.WriteByte(src[i])
				i++
			}
			continue
		}
		if c == byte(quote) {
			i++
			return result.String(), i
		}
		result.WriteByte(c)
		i++
	}
	return result.String(), i
}

// removeComments removes single-line and multi-line comments from JS/TS source
func removeComments(src string) string {
	var result strings.Builder
	i := 0
	for i < len(src) {
		// String literals - keep as-is
		if src[i] == '\'' || src[i] == '"' || src[i] == '`' {
			quote := src[i]
			result.WriteByte(src[i])
			i++
			for i < len(src) {
				c := src[i]
				result.WriteByte(c)
				if c == '\\' {
					i++
					if i < len(src) {
						result.WriteByte(src[i])
						i++
					}
					continue
				}
				if c == byte(quote) {
					i++
					break
				}
				i++
			}
			continue
		}

		// Single-line comment
		if i+1 < len(src) && src[i] == '/' && src[i+1] == '/' {
			for i < len(src) && src[i] != '\n' {
				result.WriteByte(' ')
				i++
			}
			continue
		}

		// Multi-line comment
		if i+1 < len(src) && src[i] == '/' && src[i+1] == '*' {
			result.WriteByte(' ')
			result.WriteByte(' ')
			i += 2
			for i+1 < len(src) && !(src[i] == '*' && src[i+1] == '/') {
				if src[i] == '\n' {
					result.WriteByte('\n')
				} else {
					result.WriteByte(' ')
				}
				i++
			}
			if i+1 < len(src) {
				result.WriteByte(' ')
				result.WriteByte(' ')
				i += 2
			}
			continue
		}

		result.WriteByte(src[i])
		i++
	}
	return result.String()
}

// resolveJSImport resolves an import path to an absolute file path
func resolveJSImport(dir, importPath, projectRoot string) (string, error) {
	var base string
	if strings.HasPrefix(importPath, ".") {
		base = filepath.Join(dir, importPath)
	} else {
		// Absolute path in project
		base = filepath.Join(projectRoot, importPath)
	}

	// Try exact path
	if fileExists(base) && !isDir(base) {
		abs, err := filepath.Abs(base)
		return abs, err
	}

	// Try with extensions
	extensions := []string{".ts", ".tsx", ".js", ".jsx", ".mjs", ".cjs"}
	for _, ext := range extensions {
		candidate := base + ext
		if fileExists(candidate) {
			abs, err := filepath.Abs(candidate)
			return abs, err
		}
	}

	// Try as directory with index file
	if isDir(base) {
		for _, ext := range extensions {
			candidate := filepath.Join(base, "index"+ext)
			if fileExists(candidate) {
				abs, err := filepath.Abs(candidate)
				return abs, err
			}
		}
	}

	// File not found - return error
	return "", &importError{
		msg: "could not perform relative import for '" + importPath + "' because the file or dir was not found",
	}
