	var result strings.Builder
	for i < len(src) {
		c := src[i]
		if c == '\\' {
			i++
			if i < len(src) {
				result.WriteByte(src[i])
				i++
			}
			continue
		}
		if c == byte(quote) {
			i++
			return result.String(), i
		}
		result.WriteByte(c)
		i++
	}
	return result.String(), i
