// removeComments removes single-line and multi-line comments from JS/TS source
func removeComments(src string) string {
	var result strings.Builder
	i := 0
	for i < len(src) {
		// String literals - keep as-is
		if src[i] == '\'' || src[i] == '"' || src[i] == '`' {
			quote := src[i]
			result.WriteByte(src[i])
			i++
			for i < len(src) {
				c := src[i]
				result.WriteByte(c)
				if c == '\\' {
					i++
					if i < len(src) {
						result.WriteByte(src[i])
						i++
					}
					continue
				}
				if c == byte(quote) {
					i++
					break
				}
				i++
			}
			continue
		}

		// Single-line comment
		if i+1 < len(src) && src[i] == '/' && src[i+1] == '/' {
			for i < len(src) && src[i] != '\n' {
				result.WriteByte(' ')
				i++
			}
			continue
		}

		// Multi-line comment
		if i+1 < len(src) && src[i] == '/' && src[i+1] == '*' {
			result.WriteByte(' ')
			result.WriteByte(' ')
			i += 2
			for i+1 < len(src) && !(src[i] == '*' && src[i+1] == '/') {
				if src[i] == '\n' {
					result.WriteByte('\n')
				} else {
					result.WriteByte(' ')
				}
				i++
			}
			if i+1 < len(src) {
				result.WriteByte(' ')
				result.WriteByte(' ')
				i += 2
			}
			continue
		}

		result.WriteByte(src[i])
		i++
	}
	return result.String()
}

