func resolveTSConfigPath(importPath, projectRoot, dir string) string {
	tsconfig := loadTSConfig(projectRoot)
	if tsconfig == nil {
		return ""
	}

	for pattern, targets := range tsconfig.CompilerOptions.Paths {
		if matchTSConfigPattern(pattern, importPath) {
			suffix := strings.TrimPrefix(importPath, strings.TrimSuffix(pattern, "*"))
			for _, target := range targets {
				resolved := strings.TrimSuffix(target, "*") + suffix
				abs := filepath.Join(projectRoot, resolved)
				if resolved, err := resolveJSImport(dir, abs, projectRoot); err == nil {
					return resolved
				}
				// Also try as relative to projectRoot
				if resolved, err := resolveJSImport(projectRoot, "./"+filepath.ToSlash(abs), projectRoot); err == nil {
					return resolved
				}
			}
		}
	}
	return ""
}

func matchTSConfigPattern(pattern, path string) bool {
	if strings.HasSuffix(pattern, "*") {
		prefix := pattern[:len(pattern)-1]
		return strings.HasPrefix(path, prefix)
	}
	return pattern == path
}

