		// Get the local path relative to project root
		localPath := strings.TrimPrefix(importPath, goMod.Module)
		localPath = strings.TrimPrefix(localPath, "/")

		// The import path is a directory - find Go files in it
		absDir := filepath.Join(projectRoot, localPath)

		info, err := os.Stat(absDir)
		if err != nil {
			errors = append(errors, "open "+absDir+": no such file or directory")
			continue
		}

		if !info.IsDir() {
			// It's a file directly
			if !seen[absDir] {
				seen[absDir] = true
				imports = append(imports, absDir)
			}
			continue
		}

		// Find all .go files in the directory
		goFiles, err := findGoFilesInDir(absDir)
		if err != nil {
			errors = append(errors, err.Error())
			continue
		}

		for _, gf := range goFiles {
			if !seen[gf] {
				seen[gf] = true
				imports = append(imports, gf)
			}
		}
	}

	sort.Strings(imports)
	return imports, errors
}

func findGoFilesInDir(dir string) ([]string, error) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return nil, err
	}

	var files []string
	for _, e := range entries {
		if !e.IsDir() && strings.HasSuffix(e.Name(), ".go") && !strings.HasSuffix(e.Name(), "_test.go") {
			files = append(files, filepath.Join(dir, e.Name()))
		}
	}
	return files, nil
}

// extractGoImports extracts import paths from Go source
func extractGoImports(src string) []string {
	// Find import blocks
	var paths []string
	seen := make(map[string]bool)

	// Remove comments
	cleaned := removeGoComments(src)

	// Find import declarations
	// import "path"
	// import ("path1"\n"path2")
	i := 0
	for i < len(cleaned) {
		if i+6 <= len(cleaned) && cleaned[i:i+6] == "import" && !isGoIdentChar(getCharAt(cleaned, i-1)) && !isGoIdentChar(getCharAt(cleaned, i+6)) {
			j := i + 6
			j = skipGoWhitespace(cleaned, j)

			if j < len(cleaned) && cleaned[j] == '(' {
				// Multi-import block
				j++
				for j < len(cleaned) && cleaned[j] != ')' {
					j = skipGoWhitespace(cleaned, j)
					if j < len(cleaned) && cleaned[j] == '"' {
						path, end := extractGoString(cleaned, j)
						if end > j && path != "" {
							if !seen[path] {
								seen[path] = true
								paths = append(paths, path)
							}
							j = end
						} else {
							j++
						}
					} else if j < len(cleaned) && cleaned[j] != ')' {
						// Skip identifier (alias or blank)
						for j < len(cleaned) && !isGoWhitespace(cleaned[j]) && cleaned[j] != '"' && cleaned[j] != ')' {
							j++
						}
					} else {
						break
					}
				}
			} else if j < len(cleaned) && cleaned[j] == '"' {
				// Single import
				path, end := extractGoString(cleaned, j)
				if end > j && path != "" {
					if !seen[path] {
						seen[path] = true
						paths = append(paths, path)
					}
					i = end
					continue
				}
			}
		}
		i++
	}

	return paths
}

func isGoIdentChar(c byte) bool {
	return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '_'
}

func isGoWhitespace(c byte) bool {
	return c == ' ' || c == '\t' || c == '\n' || c == '\r'
}

func getCharAt(s string, i int) byte {
	if i < 0 || i >= len(s) {
		return 0
	}
	return s[i]
}

func skipGoWhitespace(src string, i int) int {
	for i < len(src) && isGoWhitespace(src[i]) {
		i++
	}
	return i
}

func extractGoString(src string, i int) (string, int) {
	if i >= len(src) || src[i] != '"' {
		return "", i
	}
	j := i + 1
	for j < len(src) && src[j] != '"' {
		j++
	}
	if j >= len(src) {
		return "", i
	}
	return src[i+1 : j], j + 1
}

func removeGoComments(src string) string {
	var result strings.Builder
	i := 0
	for i < len(src) {
		// String literal
		if src[i] == '"' {
			start := i
			i++
			for i < len(src) && src[i] != '"' {
				if src[i] == '\\' {
					i++
				}
				i++
			}
			if i < len(src) {
				i++
			}
			result.WriteString(src[start:i])
			continue
		}

		// Single-line comment
		if i+1 < len(src) && src[i] == '/' && src[i+1] == '/' {
			for i < len(src) && src[i] != '\n' {
				result.WriteByte(' ')
				i++
			}
			continue
		}

		// Multi-line comment
		if i+1 < len(src) && src[i] == '/' && src[i+1] == '*' {
			result.WriteByte(' ')
			result.WriteByte(' ')
			i += 2
			for i+1 < len(src) && !(src[i] == '*' && src[i+1] == '/') {
				if src[i] == '\n' {
					result.WriteByte('\n')
				} else {
					result.WriteByte(' ')
				}
				i++
			}
			if i+1 < len(src) {
				result.WriteByte(' ')
				result.WriteByte(' ')
				i += 2
			}
			continue
		}

		result.WriteByte(src[i])
		i++
	}
	return result.String()
}

