package main

import (
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
)

var (
	// import X, import X as Y
	pyImportRe = regexp.MustCompile(`^(\s*)import\s+([\w.,\s]+)`)
	// from X import Y, from . import X, from .X import Y
	pyFromImportRe = regexp.MustCompile(`^(\s*)from\s+(\.{0,2}[\w.]*)?\s+import\s+`)
)

// parsePythonImports parses a Python file and returns imported local file paths
func parsePythonImports(filePath, projectRoot string, flags *Flags) ([]string, []string) {
	content, err := os.ReadFile(filePath)
	if err != nil {
		return nil, []string{err.Error()}
	}

	src := string(content)
	dir := filepath.Dir(filePath)

	var imports []string
	seen := make(map[string]bool)
	var errors []string

	lines := strings.Split(src, "\n")
	inMultiLine := false

	for _, line := range lines {
		// Skip blank lines and comments
		trimmed := strings.TrimSpace(line)
		if trimmed == "" || strings.HasPrefix(trimmed, "#") {
			continue
		}

		// Check if we're inside an if/try block (conditional import)
		isConditional := false
		if flags.PythonExcludeConditionalImports {
			// If line is indented, it might be conditional
			if len(line) > 0 && (line[0] == ' ' || line[0] == '\t') {
				isConditional = true
			}
		}

		if inMultiLine {
			if !strings.HasSuffix(trimmed, "\\") && !strings.Contains(trimmed, ")") {
				// Still in multi-line, skip
			} else {
				inMultiLine = false
			}
			continue
		}

		if strings.HasSuffix(trimmed, "\\") {
			inMultiLine = true
		}

		if isConditional {
			continue
		}

		// Parse 'from X import Y' 
		if m := pyFromImportRe.FindStringSubmatch(line); m != nil {
			modulePath := strings.TrimSpace(m[2])

			var resolved string
			var importErr string

			if strings.HasPrefix(modulePath, ".") {
				// Relative import
				resolved, importErr = resolvePythonRelativeImport(dir, modulePath)
			} else {
				// Absolute import
				resolved = resolvePythonAbsoluteImport(dir, projectRoot, modulePath)
			}

			if importErr != "" {
				errors = append(errors, importErr)
			} else if resolved != "" && !seen[resolved] {
				seen[resolved] = true
				imports = append(imports, resolved)
			}
			continue
