package main

import (
	"path/filepath"
)

// parseFileDeps determines which files a given file depends on
func parseFileDeps(filePath, projectRoot string, flags *Flags) ([]string, []string) {
	lang := detectLanguage(filePath)

	switch lang {
	case "js":
		return parseJSImports(filePath, projectRoot, flags)
	case "python":
		return parsePythonImports(filePath, projectRoot, flags)
	case "go":
		return parseGoImports(filePath, projectRoot, flags)
	case "rust":
		return parseRustImports(filePath, projectRoot, flags)
	}

	return nil, nil
}

// findProjectRootForFile finds the project root for a given file
func findProjectRootForFile(filePath string) string {
	lang := detectLanguage(filePath)
	dir := filepath.Dir(filePath)

	switch lang {
	case "js":
		// Find package.json
		root := findProjectRoot(dir, "js")
		if root != "" {
			return root
		}
	case "go":
		// Find go.mod
		root := findProjectRoot(dir, "go")
		if root != "" {
			return root
		}
	case "rust":
		// Find Cargo.toml
		root := findProjectRoot(dir, "rust")
		if root != "" {
			return root
		}
	case "python":
		// Python doesn't have a definitive root marker
		// Use the directory of the entrypoint
		return dir
	}

	return dir
}
