			// List item
			value := strings.TrimPrefix(trimmed, "- ")
			value = strings.TrimSpace(value)
			value = unquoteYAML(value)

			switch section {
			case SectionExclude:
				cfg.Exclude = append(cfg.Exclude, value)
			case SectionOnly:
				cfg.Only = append(cfg.Only, value)
			case SectionCheckEntrypoints:
				cfg.Check.Entrypoints = append(cfg.Check.Entrypoints, value)
			case SectionCheckAllow, SectionCheckAllowKey:
				if allowKeyInObject && indent >= 6 {
					// Inside allow rule object (to: [...])
					allowKeyTo = append(allowKeyTo, value)
				} else if currentAllowKey != "" {
