					if cfg.Check.Allow == nil {
						cfg.Check.Allow = make(map[string]AllowRule)
					}
					existing := cfg.Check.Allow[currentAllowKey]
					existing.Patterns = append(existing.Patterns, value)
					cfg.Check.Allow[currentAllowKey] = existing
				}
			case SectionCheckDeny, SectionCheckDenyKey:
				if currentDenyKey != "" {
					// Simple string item in deny list
					if cfg.Check.Deny == nil {
						cfg.Check.Deny = make(map[string][]DenyItem)
					}
					cfg.Check.Deny[currentDenyKey] = append(cfg.Check.Deny[currentDenyKey], DenyItem{To: value})
				}
			case SectionCheckAliases, SectionCheckAliasesKey:
				if currentAliasKey != "" {
					if cfg.Check.Aliases == nil {
						cfg.Check.Aliases = make(map[string][]string)
					}
					cfg.Check.Aliases[currentAliasKey] = append(cfg.Check.Aliases[currentAliasKey], value)
				}
			}
