			toVal := strings.TrimSpace(strings.TrimPrefix(trimmed, "- to:"))
			toVal = unquoteYAML(toVal)
			if cfg.Check.Deny == nil {
				cfg.Check.Deny = make(map[string][]DenyItem)
			}
			cfg.Check.Deny[currentDenyKey] = append(cfg.Check.Deny[currentDenyKey], DenyItem{To: toVal})
			currentKey = "deny_item_to"
			continue
		}

