			}
			cfg.Check.Deny[currentDenyKey] = append(cfg.Check.Deny[currentDenyKey], DenyItem{})
			currentKey = "deny_item_to"
			continue
		}

		// Key: value pair
		colonIdx := strings.Index(trimmed, ":")
		if colonIdx < 0 {
