						}
						existing := cfg.Check.Allow[currentAllowKey]
						existing.Patterns = allowKeyTo
						existing.Reason = allowKeyReason
						cfg.Check.Allow[currentAllowKey] = existing
					}
					currentAllowKey = unquoteYAML(key)
					allowKeyInObject = false
					allowKeyTo = nil
					allowKeyReason = ""
				}
			case SectionCheckDeny:
				// Glob pattern key
				currentDenyKey = unquoteYAML(key)
				section = SectionCheckDenyKey
				currentKey = "deny_key"
			case SectionCheckDenyKey:
				// Could be next deny key
				if indent <= 4 {
					currentDenyKey = unquoteYAML(key)
					currentKey = "deny_key"
				}
			case SectionCheckAliases:
				currentAliasKey = unquoteYAML(key)
				section = SectionCheckAliasesKey
			case SectionCheckAliasesKey:
				if indent <= 4 {
					currentAliasKey = unquoteYAML(key)
				}
			}
		case 6:
			switch section {
			case SectionCheckAllowKey:
				// 'to' list items or 'reason'
				if currentKey == "to" {
					// Already handled in list items
				}
			case SectionCheckDenyKey:
				// Sub-keys in deny items
				switch key {
				case "to":
					items := cfg.Check.Deny[currentDenyKey]
					if len(items) > 0 {
						items[len(items)-1].To = value
						cfg.Check.Deny[currentDenyKey] = items
					} else {
						if cfg.Check.Deny == nil {
							cfg.Check.Deny = make(map[string][]DenyItem)
						}
						cfg.Check.Deny[currentDenyKey] = append(cfg.Check.Deny[currentDenyKey], DenyItem{To: value})
					}
				case "reason":
					items := cfg.Check.Deny[currentDenyKey]
					if len(items) > 0 {
						items[len(items)-1].Reason = value
						cfg.Check.Deny[currentDenyKey] = items
					}
				}
			}
		}
	}

	// Save any pending allow rule
	if currentAllowKey != "" && (len(allowKeyTo) > 0 || allowKeyReason != "") {
		if cfg.Check.Allow == nil {
			cfg.Check.Allow = make(map[string]AllowRule)
		}
		existing := cfg.Check.Allow[currentAllowKey]
		if allowKeyInObject {
			existing.Patterns = allowKeyTo
			existing.Reason = allowKeyReason
		}
		cfg.Check.Allow[currentAllowKey] = existing
	}

	return nil
}

func parseBoolYAML(s string) bool {
	s = strings.ToLower(strings.TrimSpace(s))
	return s == "true" || s == "yes" || s == "1"
}

func unquoteYAML(s string) string {
	s = strings.TrimSpace(s)
	if len(s) >= 2 {
		if (s[0] == '\'' && s[len(s)-1] == '\'') || (s[0] == '"' && s[len(s)-1] == '"') {
			return s[1 : len(s)-1]
		}
	}
	return s
}

