			continue
		}

		if trimmed == "- to:" && section == SectionCheckDenyKey {
			if cfg.Check.Deny == nil {
				cfg.Check.Deny = make(map[string][]DenyItem)
			}
			cfg.Check.Deny[currentDenyKey] = append(cfg.Check.Deny[currentDenyKey], DenyItem{})
			currentKey = "deny_item_to"
			continue
		}

		// Key: value pair
		colonIdx := strings.Index(trimmed, ":")
		if colonIdx < 0 {
			continue
		}

		key := strings.TrimSpace(trimmed[:colonIdx])
		value := strings.TrimSpace(trimmed[colonIdx+1:])
		value = unquoteYAML(value)

		// Handle nested deny item properties
		if currentKey == "deny_item_to" && key == "reason" && section == SectionCheckDenyKey {
			items := cfg.Check.Deny[currentDenyKey]
			if len(items) > 0 {
				items[len(items)-1].Reason = value
				cfg.Check.Deny[currentDenyKey] = items
			}
			continue
		}

		switch indent {
		case 0:
			currentKey = key
			switch key {
			case "exclude":
				section = SectionExclude
			case "only":
				section = SectionOnly
			case "unwrapExports":
				cfg.UnwrapExports = parseBoolYAML(value)
			case "check":
				section = SectionCheck
			case "js":
				section = SectionJS
			case "python":
				section = SectionPython
			case "rust":
				section = SectionRust
			}
		case 2:
			switch section {
			case SectionCheck:
				currentKey = key
				switch key {
				case "entrypoints":
					section = SectionCheckEntrypoints
				case "allowCircularDependencies":
					cfg.Check.AllowCircularDependencies = parseBoolYAML(value)
				case "allow":
					section = SectionCheckAllow
					currentAllowKey = ""
				case "deny":
					section = SectionCheckDeny
					currentDenyKey = ""
				case "aliases":
					section = SectionCheckAliases
					currentAliasKey = ""
				}
			case SectionCheckEntrypoints:
				// Back to check level
				section = SectionCheck
				currentKey = key
				switch key {
				case "allowCircularDependencies":
					cfg.Check.AllowCircularDependencies = parseBoolYAML(value)
				case "allow":
					section = SectionCheckAllow
				case "deny":
					section = SectionCheckDeny
				case "aliases":
					section = SectionCheckAliases
				}
			case SectionCheckAllow, SectionCheckAllowKey:
				// Check if we're still inside allow section or moved to something else
				if key == "entrypoints" || key == "allowCircularDependencies" || key == "deny" || key == "aliases" {
					section = SectionCheck
					currentKey = key
					if key == "deny" {
						section = SectionCheckDeny
					} else if key == "aliases" {
						section = SectionCheckAliases
					} else if key == "allowCircularDependencies" {
						cfg.Check.AllowCircularDependencies = parseBoolYAML(value)
					}
				}
			case SectionCheckDeny, SectionCheckDenyKey:
				if key == "entrypoints" || key == "allowCircularDependencies" || key == "allow" || key == "aliases" {
					section = SectionCheck
					currentKey = key
					if key == "allow" {
						section = SectionCheckAllow
					} else if key == "aliases" {
						section = SectionCheckAliases
					}
				}
			case SectionCheckAliases, SectionCheckAliasesKey:
				if key == "entrypoints" || key == "allowCircularDependencies" || key == "allow" || key == "deny" {
					section = SectionCheck
					currentKey = key
					if key == "allow" {
						section = SectionCheckAllow
					} else if key == "deny" {
						section = SectionCheckDeny
					}
				}
			case SectionJS:
				switch key {
				case "workspaces":
					cfg.JS.Workspaces = parseBoolYAML(value)
				case "tsConfigPaths":
					cfg.JS.TsconfigPaths = parseBoolYAML(value)
				}
			case SectionPython:
				switch key {
				case "excludeConditionalImports":
					cfg.Python.ExcludeConditionalImports = parseBoolYAML(value)
				}
			}
		case 4:
			switch section {
			case SectionCheckAllow:
				// This is a key under allow: (the glob pattern)
				currentAllowKey = unquoteYAML(key)
				allowKeyInObject = false
				allowKeyTo = nil
				allowKeyReason = ""
				section = SectionCheckAllowKey

				if value != "" {
					// Inline value (shouldn't happen normally)
				}
			case SectionCheckAllowKey:
				// Sub-key under an allow key: either 'to' or 'reason'
				switch key {
				case "to":
					allowKeyInObject = true
					allowKeyTo = nil
				case "reason":
					allowKeyReason = value
					// Save the rule
					if cfg.Check.Allow == nil {
						cfg.Check.Allow = make(map[string]AllowRule)
					}
					existing := cfg.Check.Allow[currentAllowKey]
					existing.Reason = allowKeyReason
					existing.Patterns = allowKeyTo
					cfg.Check.Allow[currentAllowKey] = existing
				default:
					// New allow key at same level
					if allowKeyTo != nil || allowKeyReason != "" {
						if cfg.Check.Allow == nil {
							cfg.Check.Allow = make(map[string]AllowRule)
						}
						existing := cfg.Check.Allow[currentAllowKey]
						existing.Patterns = allowKeyTo
						existing.Reason = allowKeyReason
						cfg.Check.Allow[currentAllowKey] = existing
					}
					currentAllowKey = unquoteYAML(key)
					allowKeyInObject = false
					allowKeyTo = nil
					allowKeyReason = ""
				}
			case SectionCheckDeny:
				// Glob pattern key
				currentDenyKey = unquoteYAML(key)
				section = SectionCheckDenyKey
				currentKey = "deny_key"
			case SectionCheckDenyKey:
				// Could be next deny key
				if indent <= 4 {
					currentDenyKey = unquoteYAML(key)
					currentKey = "deny_key"
				}
			case SectionCheckAliases:
				currentAliasKey = unquoteYAML(key)
				section = SectionCheckAliasesKey
			case SectionCheckAliasesKey:
				if indent <= 4 {
					currentAliasKey = unquoteYAML(key)
				}
			}
		case 6:
			switch section {
			case SectionCheckAllowKey:
				// 'to' list items or 'reason'
				if currentKey == "to" {
					// Already handled in list items
				}
			case SectionCheckDenyKey:
				// Sub-keys in deny items
				switch key {
				case "to":
					items := cfg.Check.Deny[currentDenyKey]
					if len(items) > 0 {
						items[len(items)-1].To = value
						cfg.Check.Deny[currentDenyKey] = items
					} else {
						if cfg.Check.Deny == nil {
							cfg.Check.Deny = make(map[string][]DenyItem)
						}
						cfg.Check.Deny[currentDenyKey] = append(cfg.Check.Deny[currentDenyKey], DenyItem{To: value})
					}
				case "reason":
					items := cfg.Check.Deny[currentDenyKey]
					if len(items) > 0 {
						items[len(items)-1].Reason = value
						cfg.Check.Deny[currentDenyKey] = items
					}
				}
			}
		}
	}

	// Save any pending allow rule
	if currentAllowKey != "" && (len(allowKeyTo) > 0 || allowKeyReason != "") {
		if cfg.Check.Allow == nil {
			cfg.Check.Allow = make(map[string]AllowRule)
		}
		existing := cfg.Check.Allow[currentAllowKey]
		if allowKeyInObject {
			existing.Patterns = allowKeyTo
			existing.Reason = allowKeyReason
		}
		cfg.Check.Allow[currentAllowKey] = existing
	}

	return nil
}

func parseBoolYAML(s string) bool {
	s = strings.ToLower(strings.TrimSpace(s))
	return s == "true" || s == "yes" || s == "1"
}

func unquoteYAML(s string) string {
	s = strings.TrimSpace(s)
	if len(s) >= 2 {
		if (s[0] == '\'' && s[len(s)-1] == '\'') || (s[0] == '"' && s[len(s)-1] == '"') {
			return s[1 : len(s)-1]
		}
	}
	return s
}

