package main

import (
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

func runCheck(flags *Flags, args []string) error {
	// Load config
	configPath := flags.ConfigFile
	if !filepath.IsAbs(configPath) {
		// Try CWD
		if _, err := os.Stat(configPath); err != nil {
			return fmt.Errorf("open %s: no such file or directory", configPath)
		}
	}

	cfg, err := LoadConfig(configPath)
	if err != nil {
		return err
	}

	// Check for entrypoints
	if len(cfg.Check.Entrypoints) == 0 {
		cwd, _ := os.Getwd()
		return fmt.Errorf("config file %q has no entrypoints", cwd)
	}

	// Apply config settings to flags
	applyConfigToFlags(cfg, flags)

	// Find project root (directory of config file)
	absConfig, _ := filepath.Abs(configPath)
	projectRoot := filepath.Dir(absConfig)

	// Build dependency graph from all entrypoints
	filters := buildFilters(flags)

	// Resolve entrypoints
	var absEntrypoints []string
	for _, ep := range cfg.Check.Entrypoints {
		absEp := ep
		if !filepath.IsAbs(ep) {
			absEp = filepath.Join(projectRoot, ep)
		}
		absEntrypoints = append(absEntrypoints, absEp)
	}

	g := newGraph(projectRoot)
	if err := g.Build(absEntrypoints, flags, filters); err != nil {
		return err
	}

	// Collect all violations
	var violations []string

	// Check circular dependencies
	if !cfg.Check.AllowCircularDependencies {
		// Find all cycles across all entrypoints
		allCycles := findAllCycles(g, absEntrypoints)
		for _, cycle := range allCycles {
			violations = append(violations, "detected circular dependencies:\n- "+strings.Join(cycle, " -> "))
		}
	}

	// Expand aliases
	aliases := expandAliases(cfg.Check.Aliases, projectRoot)

	// Check deny rules
	for pattern, denyItems := range cfg.Check.Deny {
		expandedFrom := expandPattern(pattern, aliases)

		for _, node := range g.Nodes {
			fromMatches := false
			for _, ep := range expandedFrom {
				if m, _ := globMatch(ep, node.RelPath); m {
					fromMatches = true
					break
				}
			}
			if !fromMatches {
				continue
			}

			// Check if any of this node's deps match the deny rules
			for _, dep := range node.Deps {
				depNode := g.Nodes[dep]
				if depNode == nil {
					continue
				}

				for _, denyItem := range denyItems {
					expandedTo := expandPattern(denyItem.To, aliases)
					for _, toPattern := range expandedTo {
						if m, _ := globMatch(toPattern, depNode.RelPath); m {
							violation := "- " + node.RelPath + " -> " + depNode.RelPath
							if denyItem.Reason != "" {
								violation += "\n  " + denyItem.Reason
							}
							violations = append(violations, violation)
							break
						}
					}
				}
			}
		}
	}

	// Check allow rules
	for pattern, allowRule := range cfg.Check.Allow {
		expandedFrom := expandPattern(pattern, aliases)

		for _, node := range g.Nodes {
			fromMatches := false
			for _, ep := range expandedFrom {
				if m, _ := globMatch(ep, node.RelPath); m {
					fromMatches = true
					break
				}
			}
			if !fromMatches {
				continue
			}

			// Check if any dep is NOT in the allow list
			expandedPatterns := expandPatterns(allowRule.Patterns, aliases)

			for _, dep := range node.Deps {
				depNode := g.Nodes[dep]
				if depNode == nil {
					continue
