func runExplain(flags *Flags, args []string) error {
	if len(args) < 2 {
		return fmt.Errorf("explain requires two glob patterns")
	}

	leftGlob := args[0]
	rightGlob := args[1]

	// Find project root from CWD
	cwd, err := os.Getwd()
	if err != nil {
		return err
	}

	// Load config if present
	cfg, _ := loadConfigForDir(flags, cwd)
	if cfg != nil {
		applyConfigToFlags(cfg, flags)
	}

	// Expand globs to file lists
	leftFiles, err := expandGlob(leftGlob, cwd)
	if err != nil {
		return err
	}

	rightFiles, err := expandGlob(rightGlob, cwd)
	if err != nil {
		return err
	}

	// Convert to relative paths
	leftRel := toRelPaths(leftFiles, cwd)
	rightRel := toRelPaths(rightFiles, cwd)

	// Handle overlap flags
	leftSet := make(map[string]bool)
	rightSet := make(map[string]bool)
	for _, f := range leftRel {
		leftSet[f] = true
	}
	for _, f := range rightRel {
		rightSet[f] = true
	}

	if flags.OverlapLeft {
		// Keep overlap in left, remove from right
		var newRight []string
		for _, f := range rightRel {
			if !leftSet[f] {
				newRight = append(newRight, f)
			}
		}
		rightRel = newRight
		rightSet = make(map[string]bool)
		for _, f := range rightRel {
			rightSet[f] = true
		}
	} else if flags.OverlapRight {
		// Keep overlap in right, remove from left
		var newLeft []string
		for _, f := range leftRel {
			if !rightSet[f] {
				newLeft = append(newLeft, f)
			}
		}
		leftRel = newLeft
		leftSet = make(map[string]bool)
		for _, f := range leftRel {
			leftSet[f] = true
		}
