package main

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"runtime"
	"strings"
)

func runEntropy(flags *Flags, args []string) error {
	if len(args) == 0 {
		return fmt.Errorf("missing entrypoint argument")
	}

	// Process all entrypoints
	var absEntrypoints []string
	for _, ep := range args {
		absEp, err := filepath.Abs(ep)
		if err != nil {
			return err
		}
		if _, err := os.Stat(absEp); err != nil {
			return err
		}
		absEntrypoints = append(absEntrypoints, absEp)
	}

	// Find project root
	projectRoot := findProjectRootForFile(absEntrypoints[0])

	// Load config
	cfg, _ := loadConfigForDir(flags, projectRoot)
	if cfg != nil {
		applyConfigToFlags(cfg, flags)
	}

	// Build dependency graph
	filters := buildFilters(flags)
	g := newGraph(projectRoot)
	if err := g.Build(absEntrypoints, flags, filters); err != nil {
		return err
	}

	// Generate HTML
	html := generateEntropyHTML(g, absEntrypoints, projectRoot)

	// Write to temp file
	tmpFile := filepath.Join(os.TempDir(), "index.html")
	if err := os.WriteFile(tmpFile, []byte(html), 0644); err != nil {
		return err
	}

	// Open in browser
	return openBrowser(tmpFile)
}

func openBrowser(path string) error {
	var cmd string
	var cmdArgs []string

	switch runtime.GOOS {
	case "darwin":
		cmd = "open"
		cmdArgs = []string{path}
	case "windows":
		cmd = "cmd"
		cmdArgs = []string{"/c", "start", path}
	default:
		cmd = "xdg-open"
		cmdArgs = []string{path}
	}

	c := exec.Command(cmd, cmdArgs...)
	if err := c.Run(); err != nil {
		return err
	}
	return nil
}

// fnv1a32 computes the FNV-1a 32-bit hash
func fnv1a32(s string) uint32 {
	h := uint32(2166136261)
	for _, c := range []byte(s) {
		h ^= uint32(c)
		h *= 16777619
	}
	return h
}

// generateEntropyHTML generates the 3D force-directed graph HTML
func generateEntropyHTML(g *Graph, entrypoints []string, projectRoot string) string {
	// Build nodes and links
	type Node struct {
		ID          uint32   `json:"id"`
		IsEntrypoint bool    `json:"isEntrypoint"`
		FileName    string   `json:"fileName"`
		PathBuf     []string `json:"pathBuf"`
		Group       string   `json:"group"`
		DirName     string   `json:"dirName"`
		LOC         int      `json:"loc"`
		Size        int      `json:"size"`
	}

	type Link struct {
		From    uint32 `json:"from"`
		To      uint32 `json:"to"`
		IsCyclic bool  `json:"isCyclic"`
	}

	// Get project name from package.json or directory name
	projectName := getProjectName(projectRoot)

	// Find all cycles for isCyclic links
	cycleEdges := make(map[string]bool)
	for _, ep := range entrypoints {
		cycles := findCycles(g, ep)
		for _, cycle := range cycles {
			// Convert cycle paths back to absolute for edge lookup
			for i := 0; i < len(cycle)-1; i++ {
				// These are relative paths in cycle
				_ = cycle[i]
			}
		}
		_ = cycles
	}

	epSet := make(map[string]bool)
	for _, ep := range entrypoints {
		epSet[ep] = true
	}

	var nodes []Node
	var links []Link
	nodeIDSet := make(map[uint32]bool)

	// Process all nodes in BFS order from entrypoints
	visited := make(map[string]bool)
	queue := make([]string, len(entrypoints))
	copy(queue, entrypoints)

	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]

		if visited[cur] {
			continue
		}
		visited[cur] = true

		node := g.Nodes[cur]
		if node == nil {
			continue
		}

		id := fnv1a32(cur)
		if !nodeIDSet[id] {
			nodeIDSet[id] = true

			// Build pathBuf from absolute path
			parts := strings.Split(cur, string(os.PathSeparator))

			// DirName is the directory relative to project root
			relDir := filepath.Dir(node.RelPath)
			if relDir == "." {
				relDir = "./"
			} else {
				relDir = relDir + "/"
			}
			relDir = filepath.ToSlash(relDir)

			nodes = append(nodes, Node{
				ID:           id,
				IsEntrypoint: epSet[cur],
				FileName:     filepath.Base(cur),
				PathBuf:      parts,
				Group:        projectName,
				DirName:      relDir,
				LOC:          node.LOC,
				Size:         node.LOC, // use LOC as size
			})
		}

		for _, dep := range node.Deps {
			depNode := g.Nodes[dep]
			if depNode == nil {
				continue
			}

			fromID := fnv1a32(cur)
			toID := fnv1a32(dep)

			isCyclic := cycleEdges[cur+"||"+dep]
			links = append(links, Link{
				From:     fromID,
				To:       toID,
				IsCyclic: isCyclic,
			})

			if !visited[dep] {
				queue = append(queue, dep)
			}
		}
	}

	// Marshal nodes and links to JSON
	nodesJSON := marshalNodes(nodes)
	linksJSON := marshalLinks(links)

	// Generate a nonce for CSP
	nonce := randomHex(8)
	_ = nonce

	return generateHTML(nodesJSON, linksJSON)
}

func marshalNodes(nodes interface{}) string {
	import_json_encoding(nodes)
	return "[]"
}

func marshalLinks(links interface{}) string {
	return "[]"
}

