package main

import (
	"bufio"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"syscall"
	"unicode/utf8"
	"unsafe"
)

// Colors
const (
	colorReset   = "\x1b[39m"
	colorGreen   = "\x1b[32m"
	colorCyan    = "\x1b[36m"
	colorMagenta = "\x1b[35m"
	colorRed     = "\x1b[31m"
)

// Terminal size
func getTerminalSize() (width, height int) {
	type winsize struct {
		Row    uint16
		Col    uint16
		Xpixel uint16
		Ypixel uint16
	}
	ws := &winsize{}
	retCode, _, _ := syscall.Syscall(syscall.SYS_IOCTL,
		uintptr(syscall.Stdout),
		uintptr(syscall.TIOCGWINSZ),
		uintptr(unsafe.Pointer(ws)))
	if retCode == 0 {
		return int(ws.Col), int(ws.Row)
	}
	return 80, 24 // default
}

// TreeLine represents a single line in the tree display
type TreeLine struct {
	// The "prefix" columns (tree structure)
	Prefix string
	// The node name
	Name string
	// The absolute path of the node this line belongs to
	NodePath string
	// Whether this is a "connector only" line (no node)
	IsConnector bool
	// Connection style for multi-parent nodes
	// Each parent has a connection column
	ParentCols []parentCol
	// Has children indicator
	HasChildren bool
}

type parentCol struct {
	parentPath string
	connector  connectorType
}

type connectorType int

const (
	connNone    connectorType = iota
	connPipe    // │
	connCorner  // └
	connTee     // ├
	connMerge   // ┴
	connArrow   // ▷
	connH       // ─
)

// treeView holds the state of the tree view
type treeView struct {
	g          *Graph
	entrypoint string
	result     *TreeResult

	// All nodes in BFS order
	bfsOrder []string
	// Current selected node index (-1 = root, 0-n = nodes in order)
	cursor int
	// Scroll offset (which line to start rendering from)
	scrollOffset int
	// Width and height of terminal
	width  int
	height int

	// Pre-computed tree lines
	lines []treeDisplayLine
}

type treeDisplayLine struct {
	text     string     // plain text
	nodePath string     // which node this line belongs to (for selection)
	isNode   bool       // is this a node line (not connector)
}

func runTreeTUI(g *Graph, entrypoint string, result *TreeResult) error {
	width, height := getTerminalSize()

	tv := &treeView{
		g:          g,
		entrypoint: entrypoint,
		result:     result,
		width:      width,
		height:     height,
	}

	// Build BFS order
	tv.bfsOrder = buildBFSOrder(g, entrypoint)

	// Pre-compute tree lines
	tv.computeLines()

	// Set up raw terminal
	oldState, err := makeRaw()
	if err != nil {
		return fmt.Errorf("exit status 1")
	}
	defer restoreTerminal(oldState)

	// Clear screen
	fmt.Print("\x1b[2J\x1b[H")

	// Initial cursor position is "root selected" (-1)
	// Actually the first position is the root (index 0 in bfsOrder)
	tv.cursor = 0
	tv.scrollOffset = 0

	tv.render()

	// Main event loop
	reader := bufio.NewReader(os.Stdin)
	for {
		b, err := reader.ReadByte()
		if err != nil {
			break
		}

		switch b {
		case 'q', 3: // q or Ctrl+C
			fmt.Print("\x1b[2J\x1b[H")
			return nil
		case 27: // ESC
			// Read escape sequence
			b2, err := reader.ReadByte()
			if err != nil || b2 != '[' {
				continue
			}
			b3, err := reader.ReadByte()
			if err != nil {
				continue
			}
			switch b3 {
			case 'A': // Up arrow
				tv.moveCursor(-1)
			case 'B': // Down arrow
				tv.moveCursor(1)
			case 'C': // Right arrow
				// No action
			case 'D': // Left arrow
				// No action
			}
		}

