	// Actually the first position is the root (index 0 in bfsOrder)
	tv.cursor = 0
	tv.scrollOffset = 0

	tv.render()

	// Main event loop
	reader := bufio.NewReader(os.Stdin)
	for {
		b, err := reader.ReadByte()
		if err != nil {
			break
		}

		switch b {
		case 'q', 3: // q or Ctrl+C
			fmt.Print("\x1b[2J\x1b[H")
			return nil
		case 27: // ESC
			// Read escape sequence
			b2, err := reader.ReadByte()
			if err != nil || b2 != '[' {
				continue
			}
			b3, err := reader.ReadByte()
			if err != nil {
				continue
			}
			switch b3 {
			case 'A': // Up arrow
				tv.moveCursor(-1)
			case 'B': // Down arrow
				tv.moveCursor(1)
			case 'C': // Right arrow
				// No action
			case 'D': // Left arrow
				// No action
			}
		}

		tv.render()
	}

	return nil
}

