// moveCursor moves the cursor by delta
func (tv *treeView) moveCursor(delta int) {
	// Navigation states:
	// 0: root selected
	// 1: unselected
	// 2, 4, 6...: each node selected (in BFS order, skipping root)
	// Odd numbers: unselected transitions

	// The selectable "items" in the tree are the nodes in BFS order
	// Between each pair of consecutive nodes, there's an "unselected" state

