func (tv *treeView) updateScroll() {
	selectedLine := tv.getSelectedLine()
	if selectedLine < 0 {
		return
	}

	if selectedLine < tv.scrollOffset {
		tv.scrollOffset = selectedLine
	}
	if selectedLine >= tv.scrollOffset+tv.height {
		tv.scrollOffset = selectedLine - tv.height + 1
	}
}

