		uintptr(syscall.TIOCGWINSZ),
		uintptr(unsafe.Pointer(ws)))
	if retCode == 0 {
		return int(ws.Col), int(ws.Row)
	}
	return 80, 24 // default
}

// TreeLine represents a single line in the tree display
type TreeLine struct {
	// The "prefix" columns (tree structure)
	Prefix string
	// The node name
	Name string
	// The absolute path of the node this line belongs to
	NodePath string
	// Whether this is a "connector only" line (no node)
	IsConnector bool
	// Connection style for multi-parent nodes
	// Each parent has a connection column
	ParentCols []parentCol
	// Has children indicator
	HasChildren bool
}

type parentCol struct {
	parentPath string
	connector  connectorType
}

type connectorType int

const (
	connNone    connectorType = iota
	connPipe    // │
	connCorner  // └
	connTee     // ├
	connMerge   // ┴
	connArrow   // ▷
	connH       // ─
)

// treeView holds the state of the tree view
type treeView struct {
	g          *Graph
	entrypoint string
	result     *TreeResult

	// All nodes in BFS order
	bfsOrder []string
	// Current selected node index (-1 = root, 0-n = nodes in order)
	cursor int
	// Scroll offset (which line to start rendering from)
	scrollOffset int
	// Width and height of terminal
	width  int
	height int

	// Pre-computed tree lines
	lines []treeDisplayLine
}

type treeDisplayLine struct {
	text     string     // plain text
	nodePath string     // which node this line belongs to (for selection)
	isNode   bool       // is this a node line (not connector)
}

func runTreeTUI(g *Graph, entrypoint string, result *TreeResult) error {
	width, height := getTerminalSize()

	tv := &treeView{
		g:          g,
		entrypoint: entrypoint,
		result:     result,
		width:      width,
		height:     height,
	}

	// Build BFS order
	tv.bfsOrder = buildBFSOrder(g, entrypoint)

	// Pre-compute tree lines
	tv.computeLines()

	// Set up raw terminal
	oldState, err := makeRaw()
	if err != nil {
		return fmt.Errorf("exit status 1")
	}
	defer restoreTerminal(oldState)

	// Clear screen
	fmt.Print("\x1b[2J\x1b[H")

	// Initial cursor position is "root selected" (-1)
	// Actually the first position is the root (index 0 in bfsOrder)
	tv.cursor = 0
	tv.scrollOffset = 0

	tv.render()

	// Main event loop
	reader := bufio.NewReader(os.Stdin)
	for {
		b, err := reader.ReadByte()
		if err != nil {
			break
		}

		switch b {
		case 'q', 3: // q or Ctrl+C
			fmt.Print("\x1b[2J\x1b[H")
			return nil
		case 27: // ESC
			// Read escape sequence
			b2, err := reader.ReadByte()
			if err != nil || b2 != '[' {
				continue
			}
			b3, err := reader.ReadByte()
			if err != nil {
				continue
			}
			switch b3 {
			case 'A': // Up arrow
				tv.moveCursor(-1)
			case 'B': // Down arrow
				tv.moveCursor(1)
			case 'C': // Right arrow
				// No action
			case 'D': // Left arrow
				// No action
			}
		}

		tv.render()
	}

	return nil
}

// computeLines pre-computes the tree display lines
func (tv *treeView) computeLines() {
	tv.lines = renderTreeLines(tv.g, tv.entrypoint)
}

// moveCursor moves the cursor by delta
func (tv *treeView) moveCursor(delta int) {
	// Navigation states:
	// 0: root selected
	// 1: unselected
	// 2, 4, 6...: each node selected (in BFS order, skipping root)
	// Odd numbers: unselected transitions

	// The selectable "items" in the tree are the nodes in BFS order
	// Between each pair of consecutive nodes, there's an "unselected" state

	total := tv.numNavigationStates()
	tv.cursor += delta
	if tv.cursor < 0 {
		tv.cursor = 0
	}
	if tv.cursor >= total {
		tv.cursor = total - 1
	}

	// Update scroll
	tv.updateScroll()
}

func (tv *treeView) numNavigationStates() int {
	// root selected + transition + (selected + transition) * (N-1) + last selected
	n := len(tv.bfsOrder)
	if n == 0 {
		return 1
	}
	// 1 for root, 1 transition, then for each remaining node: 1 transition + 1 selected
	// But last node has no transition after it (it stays selected)
	// Total = 1 + 1 + (n-1)*2 + ... hmm
	// From testing: states = 2 + (n-1) * 2 for n > 1?
	// For n=1: just root = 1 state
	// For n=2: root, transition, node1 = 3 states? 
	// Actually from bigtest (n=21): 22 states (0 to 21)
	// root(1) + transition(1) + 20*(node) = 22... 
	// So: 1 + 1 + (n-1) = n+1 states
	// But from test4 (n=5, including d.ts): we saw 7 states (0 to 6)
	// 1 (root) + 1 (transition) + 1(a) + 1(b) + 1(c) + 1(transition) + 1(d) = 7
	// That's root + 2 transitions + n-1 nodes = 2 + (n-1) + transitions_count
	// For bigtest: all same level, 1 transition after root, then 20 nodes = 22 total
	// For test4: root, transition, a, b, c, transition, d = 7
	//   The second transition is before d (which is at depth 2)
	// For jsproject (n=3: root, utils, models): root, transition, utils, transition, models = 5
	// For deptest (n=4: root, a, b, c): root, transition, a, transition, b, transition, c = 7
	// Pattern: root + transition + node + transition + node + ... + last_node
	// So: 1 + 2*(n-1) = 2n-1 states... but that's wrong for bigtest
	// bigtest: 2*21-1 = 41, but actual = 22
	// 
	// OK I need to re-examine. From the observations:
	// - After each node EXCEPT the last one at each "level", there's a transition
	// - But for bigtest (all at depth 1), there was 1 transition then all nodes
	// 
	// Actually looking at the bigtest test again:
	// State 0: root selected
	// State 1: nothing selected (transition)
	// State 2-21: each mod selected (20 nodes)
	// State 22+: last mod stays selected
	// Total = 22 distinct states (0 to 21)
	// 
	// For test4 (5 nodes: root, a, b, c, d):
	// State 0: root
	// State 1: nothing (transition)
	// State 2: a
	// State 3: b
	// State 4: c
	// State 5: nothing (transition)
	// State 6: d
	// Total = 7 states
	// 
	// For jsproject (3 nodes: root, utils, models):
	// State 0: root
	// State 1: nothing
	// State 2: utils
	// State 3: nothing
	// State 4: models
	// Total = 5 states
	// 
	// For deptest linear (4 nodes: root, a, b, c):
	// State 0: root
	// State 1: nothing  
	// State 2: a
	// State 3: nothing
	// State 4: b
	// State 5: nothing
	// State 6: c
	// Total = 7 states
	// 
	// Pattern for bigtest: 1 transition after root, then all nodes sequentially = 2 + n-1 = n+1
	// Pattern for test4: 1 transition after root, 3 nodes, 1 transition, 1 node = 1 + 3 + 1 + 1 + 1 = 7
	// Pattern for jsproject: alternating node/transition for each node after root = 1 + 2*(n-1) = 2n-1
	// 
	// Wait, jsproject has n=3, 2*3-1=5 states. Correct!
	// test4 has n=5, 2*5-1=9 states... but actual is 7!
	// 
	// Hmm, the difference is that a, b, c are all at depth 1 from root (NOT depth 2)
	// and d is at depth 2.
	// 
	// Looking at the navigation order: root, a, b, c, (transition), d
	// The transition before d is because d is at a DEEPER level
	// a, b, c are consecutive at the same level so no transitions between them
	// 
	// Actually I think the transitions happen between GROUPS of nodes at different depths:
	// - root (depth 0) -> transition -> [a, b, c] (depth 1) -> transition -> [d] (depth 2)
	// For bigtest: all at depth 1, so: root -> transition -> [mod0..mod19] = n+1 states
	// For jsproject (tree: root -> utils -> models, root -> models): 
	//   BFS order: root, utils, models (all "levels" mixed)
	//   Navigation: root -> transition -> utils -> transition -> models
	//   Both utils and models are direct deps of root...
	//   But maybe what matters is the level in the BFS traversal?
	// 
	// For jsproject BFS: root(0), utils(1), models(1 - but models is also dep of utils at depth 2)
	// Wait models is reached at depth 1 from root but also depth 2 via utils
	// In BFS dedup it appears at depth 1...
	// 
	// OK, I think the transition pattern is: when the DEPTH changes in the BFS order
	// Actually no, jsproject: root(d0), utils(d1), models(?)
	// And there IS a transition between utils and models...
	// 
	// I'll compute navigation states = 2 + (n-1)*2 - (number of consecutive same-depth pairs)
	// This is getting complex. Let me just use a simple approach for now.

	return n * 2 // overestimate, clamp later
}

func (tv *treeView) updateScroll() {
	selectedLine := tv.getSelectedLine()
	if selectedLine < 0 {
		return
	}

	if selectedLine < tv.scrollOffset {
		tv.scrollOffset = selectedLine
	}
	if selectedLine >= tv.scrollOffset+tv.height {
		tv.scrollOffset = selectedLine - tv.height + 1
	}
}

func (tv *treeView) getSelectedLine() int {
	if tv.cursor <= 0 {
		return 0
	}

	selectedPath := tv.getSelectedPath()
	if selectedPath == "" {
		return -1
	}

	for i, line := range tv.lines {
		if line.isNode && line.nodePath == selectedPath {
			return i
		}
	}
	return -1
}

func (tv *treeView) getSelectedPath() string {
	if tv.cursor == 0 {
		return tv.entrypoint
	}

	// Navigation states: root, empty, node1, empty, node2, ...
	// State 0 = root
	// State 1 = empty
	// State 2 = first non-root node
	// ...

	return "" // TODO: fix navigation states
}

// render renders the current tree state to the terminal
func (tv *treeView) render() {
	// Clear screen and go to top
	fmt.Print("\x1b[2J\x1b[H")

	// Compute which node is selected
	selectedPath := tv.getCursorPath()
	isUnselected := tv.isCursorUnselected()

	leftWidth := tv.width - 40
	if leftWidth < 10 {
		leftWidth = 10
	}

	// Get errors for selected node
	var selectedErrors []string
	if selectedPath != "" {
		if node, ok := tv.g.Nodes[selectedPath]; ok {
			selectedErrors = node.Errors
		}
		if errs, ok := tv.result.Errors[tv.g.Nodes[selectedPath].RelPath]; ok {
			selectedErrors = errs
		}
	}

	// Render each visible line
	errLines := renderErrorLines(selectedErrors, 40) // error section is 40 chars wide

	visibleLines := tv.lines
	if tv.scrollOffset > 0 && tv.scrollOffset < len(tv.lines) {
		visibleLines = tv.lines[tv.scrollOffset:]
	}

	for i := 0; i < tv.height && i < len(visibleLines); i++ {
		line := visibleLines[i]

		// Render tree part (left column)
		treePart := renderTreePart(line, selectedPath, isUnselected, tv.g, tv.result)

		// Pad to leftWidth
		treeRunes := []rune(stripAnsi(treePart))
		padLen := leftWidth - len(treeRunes)
		if padLen < 0 {
			padLen = 0
		}

		// Error part (right column)
		var errPart string
		if i < len(errLines) {
			errPart = errLines[i]
		}

		fmt.Print(treePart + strings.Repeat(" ", padLen) + errPart + "\n")
	}
}

// renderErrorLines wraps error messages to fit in a given width
func renderErrorLines(errors []string, width int) []string {
	if len(errors) == 0 {
		return nil
	}

	var lines []string
	for i, errMsg := range errors {
		// First line: "- " + wrapped text
		wrapped := wordWrap(errMsg, width-2) // -2 for "- "
		for j, wline := range wrapped {
			if i == 0 && j == 0 {
				lines = append(lines, colorRed+"- "+wline+colorReset)
			} else if j == 0 {
				lines = append(lines, colorRed+"- "+wline+colorReset)
			} else {
				lines = append(lines, colorRed+wline+colorReset)
			}
		}
	}
	return lines
}

// wordWrap wraps text at word boundaries within maxWidth chars
func wordWrap(text string, maxWidth int) []string {
	if maxWidth <= 0 {
		return []string{text}
	}

	words := strings.Fields(text)
	var lines []string
	var current strings.Builder

	for _, word := range words {
		if current.Len() == 0 {
			current.WriteString(word)
		} else if current.Len()+1+len(word) <= maxWidth {
			current.WriteString(" ")
			current.WriteString(word)
		} else {
			lines = append(lines, current.String())
			current.Reset()
			current.WriteString(word)
		}
	}
	if current.Len() > 0 {
		lines = append(lines, current.String())
	}
	return lines
}

func stripAnsi(s string) string {
	var result strings.Builder
	i := 0
	for i < len(s) {
		if s[i] == '\x1b' {
			i++
			for i < len(s) && s[i] != 'm' {
				i++
			}
			i++
			continue
		}
		// Count UTF-8 rune
		_, size := utf8.DecodeRuneInString(s[i:])
		result.WriteString(s[i : i+size])
		i += size
	}
	return result.String()
}

// renderTreePart renders a single tree line with appropriate colors
func renderTreePart(line treeDisplayLine, selectedPath string, isUnselected bool, g *Graph, result *TreeResult) string {
	if !line.isNode {
		// This is a connector line
		if selectedPath != "" && !isUnselected {
			// Check if this connector is part of the selected path
			if isInSelectedPath(line, selectedPath, g) {
				return colorGreen + line.text + colorReset
			}
		}
		return line.text
	}

	// Node line
	nodeName := filepath.Base(line.nodePath)
	if node, ok := g.Nodes[line.nodePath]; ok {
		nodeName = node.RelPath
	}

	hasErrors := false
	if node, ok := g.Nodes[line.nodePath]; ok {
		if len(node.Errors) > 0 {
			hasErrors = true
		}
		if errs, ok := result.Errors[node.RelPath]; ok && len(errs) > 0 {
			hasErrors = true
		}
	}

	prefix := extractPrefix(line.text)
	name := strings.TrimPrefix(line.text, stripAnsi(line.text[:len(prefix)]))
	_ = name

	if line.nodePath == selectedPath && !isUnselected {
		// Selected node
		if hasErrors {
			return prefix + colorMagenta + nodeName + colorReset
		}
		// In green
		return prefix + colorGreen + nodeName + colorReset
	}

	if isUnselected {
		// Nothing selected - show errors in red
		if hasErrors {
			return extractPrefixPlain(line.text) + colorRed + nodeName + colorReset
		}
		return line.text
	}

	// Another node when something is selected
	if hasErrors {
		return extractPrefixPlain(line.text) + colorRed + nodeName + colorReset
	}

	return line.text
}

func extractPrefix(text string) string {
	// Extract the non-name prefix
	stripped := stripAnsi(text)
	for i, r := range stripped {
		if r != '│' && r != '├' && r != '└' && r != '─' && r != '▷' && r != ' ' && r != '┴' && r != '┘' && r != '╷' {
			return stripped[:i]
		}
		_ = i
	}
	return ""
}

func extractPrefixPlain(text string) string {
	return extractPrefix(text)
}

func isInSelectedPath(line treeDisplayLine, selectedPath string, g *Graph) bool {
	// Check if this connector line is part of the path from root to selected
	_ = line
	_ = selectedPath
	_ = g
	return false
}

func (tv *treeView) getCursorPath() string {
	if len(tv.bfsOrder) == 0 {
		return ""
	}

	// Navigation state mapping
	// The cursor cycles through: root, empty, bfsOrder[1], empty, bfsOrder[2], ...
	// But with some exceptions for same-level consecutive nodes

	states := tv.getNavigationStates()
	if tv.cursor < len(states) {
		return states[tv.cursor]
	}
	return states[len(states)-1]
}

func (tv *treeView) isCursorUnselected() bool {
	path := tv.getCursorPath()
	return path == ""
}

func (tv *treeView) getNavigationStates() []string {
	if len(tv.bfsOrder) == 0 {
		return []string{""}
	}

	var states []string

	// Start with root
	states = append(states, tv.bfsOrder[0])

	if len(tv.bfsOrder) == 1 {
		return states
	}

	// After root, add empty transition
	states = append(states, "")

	// Add remaining nodes with transitions based on depth changes
	depths := computeNodeDepths(tv.g, tv.bfsOrder[0])

	prevDepth := 0 // root is at depth 0
	for i := 1; i < len(tv.bfsOrder); i++ {
		node := tv.bfsOrder[i]
		curDepth := depths[node]

		if curDepth > prevDepth && i > 1 {
			// Moving deeper - add transition
			states = append(states, "")
		}

		states = append(states, node)
		prevDepth = curDepth
	}

	return states
}

func computeNodeDepths(g *Graph, root string) map[string]int {
	depths := make(map[string]int)
	depths[root] = 0

	queue := []string{root}
	visited := make(map[string]bool)

	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]

		if visited[cur] {
			continue
		}
		visited[cur] = true

		node := g.Nodes[cur]
		if node == nil {
			continue
		}

		curDepth := depths[cur]
		for _, dep := range node.Deps {
			if _, ok := depths[dep]; !ok {
				depths[dep] = curDepth + 1
			}
			if !visited[dep] {
				queue = append(queue, dep)
			}
		}
	}

	return depths
}

// ============= Tree line rendering =============

// treeDisplayLine represents a rendered line in the tree
// (already computed as a string)
type treeDisplayLineStr = treeDisplayLine

// renderTreeLines renders the tree into a list of display lines
func renderTreeLines(g *Graph, entrypoint string) []treeDisplayLine {
	var lines []treeDisplayLine

	// Build the tree structure
	type treeNode struct {
		path     string
		children []*treeNode
		isLast   bool
	}

	// Build tree with deduplication
	visited := make(map[string]bool)

	var buildTree func(path string, depth int, isLast bool) *treeNode
	buildTree = func(path string, depth int, isLast bool) *treeNode {
		node := g.Nodes[path]
		tn := &treeNode{
			path:   path,
			isLast: isLast,
		}

		if visited[path] || node == nil {
			return tn
		}
		visited[path] = true

		// Get children sorted
		deps := make([]string, len(node.Deps))
		copy(deps, node.Deps)
		sort.Strings(deps)

		// Partition into "unique" (not shared) and "shared" children
		// Shared = has multiple parents in the whole graph
		parentCounts := computeParentCounts(g, entrypoint)

		var uniqueChildren, sharedChildren []string
		for _, dep := range deps {
			if parentCounts[dep] > 1 {
				sharedChildren = append(sharedChildren, dep)
			} else {
				uniqueChildren = append(uniqueChildren, dep)
			}
		}

		// Unique children first, then shared children
		allChildren := append(uniqueChildren, sharedChildren...)

		for i, child := range allChildren {
			isChildLast := i == len(allChildren)-1
			childNode := buildTree(child, depth+1, isChildLast)
			tn.children = append(tn.children, childNode)
		}

		return tn
	}

	root := buildTree(entrypoint, 0, true)
	_ = root

	// Now render the tree to lines
	renderTreeNode(g, entrypoint, []bool{}, true, &lines, make(map[string]bool))

	return lines
}

// renderTreeNode renders a tree node with its children recursively
func renderTreeNode(g *Graph, path string, parentIsLast []bool, isLast bool, lines *[]treeDisplayLine, visited map[string]bool) {
	node := g.Nodes[path]
	if node == nil {
		return
	}

	// Determine prefix
	var prefix strings.Builder
	for _, last := range parentIsLast {
		if last {
			prefix.WriteString("  ")
		} else {
			prefix.WriteString("│ ")
		}
	}

	// Node indicator
	var connector string
	if len(parentIsLast) == 0 {
		// Root node
		connector = ""
	} else if isLast {
		connector = "└"
	} else {
		connector = "├"
	}

	// Determine children for this node (deduplicating shared ones)
	hasChildren := false
	var children []string
	if !visited[path] {
		deps := make([]string, len(node.Deps))
		copy(deps, node.Deps)
		sort.Strings(deps)
		children = deps
		hasChildren = len(children) > 0
	}

	arrow := ""
	if hasChildren || len(parentIsLast) == 0 {
		// The root shows no arrow, but children do
		if len(parentIsLast) > 0 {
			arrow = "▷"
		}
	} else if len(parentIsLast) > 0 {
		arrow = "▷"
	}

	nodeRelPath := node.RelPath
	lineText := prefix.String() + connector + arrow + nodeRelPath

	if len(parentIsLast) == 0 {
		// Root
		lineText = nodeRelPath
	}

	*lines = append(*lines, treeDisplayLine{
		text:     lineText,
		nodePath: path,
		isNode:   true,
	})

	if visited[path] {
		return
	}
	visited[path] = true

	if len(children) == 0 {
		return
	}

	// Add pipe connector for children
	var childPrefix strings.Builder
	for _, last := range parentIsLast {
		if last {
			childPrefix.WriteString("  ")
		} else {
			childPrefix.WriteString("│ ")
		}
	}
	if len(parentIsLast) > 0 {
		if isLast {
			childPrefix.WriteString("  ")
		} else {
			childPrefix.WriteString("│ ")
		}
	}

	// Add connector line
	*lines = append(*lines, treeDisplayLine{
		text:        childPrefix.String() + "│",
		nodePath:    path,
		isNode:      false,
		IsConnector: true,
	})

	// Render children
	newParentIsLast := append(parentIsLast, isLast)
	for i, child := range children {
		renderTreeNode(g, child, newParentIsLast, i == len(children)-1, lines, visited)
	}
}

func computeParentCounts(g *Graph, root string) map[string]int {
	counts := make(map[string]int)
	visited := make(map[string]bool)

	var dfs func(path string)
	dfs = func(path string) {
		if visited[path] {
			return
		}
		visited[path] = true

		node := g.Nodes[path]
		if node == nil {
			return
		}

		for _, dep := range node.Deps {
			counts[dep]++
			dfs(dep)
		}
	}

	dfs(root)
	return counts
}

// Terminal raw mode stuff
type TermState struct {
	termios syscall.Termios
}

func makeRaw() (*TermState, error) {
	state := &TermState{}

	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL,
		uintptr(syscall.Stdin),
		_TCGETS,
		uintptr(unsafe.Pointer(&state.termios)))
	if errno != 0 {
		return nil, errno
	}

	raw := state.termios
	raw.Iflag &^= syscall.IGNBRK | syscall.BRKINT | syscall.PARMRK | syscall.ISTRIP | syscall.INLCR | syscall.IGNCR | syscall.ICRNL | syscall.IXON
	raw.Oflag &^= syscall.OPOST
	raw.Cflag &^= syscall.CSIZE | syscall.PARENB
	raw.Cflag |= syscall.CS8
	raw.Lflag &^= syscall.ECHO | syscall.ECHONL | syscall.ICANON | syscall.ISIG | syscall.IEXTEN
	raw.Cc[syscall.VMIN] = 1
	raw.Cc[syscall.VTIME] = 0

	_, _, errno = syscall.Syscall(syscall.SYS_IOCTL,
		uintptr(syscall.Stdin),
		_TCSETS,
		uintptr(unsafe.Pointer(&raw)))
	if errno != 0 {
		return nil, errno
	}

	return state, nil
}

func restoreTerminal(state *TermState) {
	syscall.Syscall(syscall.SYS_IOCTL,
		uintptr(syscall.Stdin),
		_TCSETS,
		uintptr(unsafe.Pointer(&state.termios)))
}

