		plainLen := visibleLen(treePart)
		if plainLen < leftWidth {
			treePart += strings.Repeat(" ", leftWidth-plainLen)
		}

		var errPart string
		if i < len(errDisplayLines) {
			errPart = errDisplayLines[i]
		}

		fmt.Print(treePart + errPart + "\n")
	}
}

// colorTreeLine applies color to a tree display line based on selection state
func (tv *treeViewState) colorTreeLine(line displayLine, selectedPath string, isUnselected bool) string {
	nodeName := ""
	if line.nodePath != "" {
		if node, ok := tv.g.Nodes[line.nodePath]; ok {
			nodeName = node.RelPath
		}
	}

	hasErrors := false
	if line.nodePath != "" {
		if node, ok := tv.g.Nodes[line.nodePath]; ok {
			if len(node.Errors) > 0 {
				hasErrors = true
			}
			if errs, ok := tv.result.Errors[node.RelPath]; ok && len(errs) > 0 {
				hasErrors = true
			}
		}
	}

	if !line.isNode {
		// Connector line
		if !isUnselected && selectedPath != "" {
			// Check if part of selected path
			if isPartOfSelectedPath(line, selectedPath, tv.g) {
				return colorGreen + line.text + colorReset
			}
		}
		return line.text
	}

	// Node line - extract prefix (box-drawing chars) and name
	prefix := extractBoxPrefix(line.text)

	if line.nodePath == selectedPath && !isUnselected {
		// This is the selected node
		if hasErrors {
			return prefix + colorMagenta + nodeName + colorReset
		}
		return prefix + colorGreen + nodeName + colorReset
	}

	if isUnselected {
		if hasErrors {
			return prefix + colorRed + nodeName + colorReset
		}
		return line.text
	}

	// A different node when something is selected
	if hasErrors {
		return prefix + colorRed + nodeName + colorReset
	}

	// If the selected path is ancestor of this node, colorize
	// For now just return plain
	return line.text
}

func isPartOfSelectedPath(line displayLine, selectedPath string, g *Graph) bool {
	// A connector line is "part of selected path" if the selected node
	// has this line's node as an ancestor or descendant
	_ = line
	_ = selectedPath
	_ = g
	return false
}

// extractBoxPrefix extracts the box-drawing character prefix from a line
func extractBoxPrefix(line string) string {
	stripped := stripAnsi(line)
	for i, r := range stripped {
		if !isBoxDrawingChar(r) && r != ' ' {
			return stripped[:i]
		}
		_ = i
	}
	return ""
}

func isBoxDrawingChar(r rune) bool {
	return r == '│' || r == '├' || r == '└' || r == '─' || r == '▷' || r == '┴' || r == '╷'
}

// computeErrorLines formats errors for display
func computeErrorLines(errors []string) []string {
	if len(errors) == 0 {
		return nil
	}

	// Error section width is 40 chars
	// First line of each error: "- " + text (max 38 chars per line)
	// Continuation: text (max 40 chars per line)
	var lines []string

	for i, errMsg := range errors {
		_ = i
		// Wrap at 36 chars (observed from testing)
		wrapped := wordWrap(errMsg, 36)
		for j, wline := range wrapped {
			if j == 0 {
				lines = append(lines, colorRed+"- "+wline+colorReset)
			} else {
				lines = append(lines, colorRed+wline+colorReset)
			}
		}
	}

	return lines
}

// wordWrap wraps text at word boundaries
func wordWrap(text string, maxWidth int) []string {
	if maxWidth <= 0 {
		return []string{text}
	}

	words := strings.Fields(text)
	var lines []string
	var current strings.Builder

	for _, word := range words {
		if current.Len() == 0 {
			current.WriteString(word)
		} else if current.Len()+1+len(word) <= maxWidth {
			current.WriteString(" ")
			current.WriteString(word)
		} else {
			lines = append(lines, current.String())
			current.Reset()
			current.WriteString(word)
		}
	}
	if current.Len() > 0 {
		lines = append(lines, current.String())
	}
	if len(lines) == 0 {
		return []string{""}
	}
	return lines
}

// visibleLen returns the visible (non-ANSI) character count
func visibleLen(s string) int {
	stripped := stripAnsi(s)
	n := 0
	for _, r := range stripped {
		_ = r
		n++
	}
	return n
}

// stripAnsi removes ANSI escape sequences
func stripAnsi(s string) string {
	var result strings.Builder
	i := 0
	for i < len(s) {
		if s[i] == '\x1b' {
			i++
			for i < len(s) && s[i] != 'm' {
				i++
			}
			i++
			continue
		}
		_, size := utf8.DecodeRuneInString(s[i:])
		result.WriteString(s[i : i+size])
		i += size
	}
	return result.String()
}

// buildNavStates builds the navigation states for the tree
// Each state is either a node path (selected) or "" (unselected)
func buildNavStates(g *Graph, entrypoint string, bfsOrder []string) []string {
	if len(bfsOrder) == 0 {
		return []string{""}
	}

	var states []string

	// Root is always first
	states = append(states, bfsOrder[0])

	if len(bfsOrder) == 1 {
		return states
	}

	// Add transition after root
	states = append(states, "")

	// Add remaining nodes
	// Determine when to add transition states:
	// Transitions happen based on "depth groups" in the BFS order
	depths := computeNodeDepths(g, entrypoint)

	prevDepth := 0 // root at depth 0
	for i := 1; i < len(bfsOrder); i++ {
		node := bfsOrder[i]
		curDepth := depths[node]

		// If depth increases, add transition (but only after at least one node at prev depth)
		if curDepth > prevDepth && i > 1 {
			states = append(states, "")
		}

		states = append(states, node)
		prevDepth = curDepth
	}

	return states
}

// computeNodeDepths computes BFS depth for each node
func computeNodeDepths(g *Graph, root string) map[string]int {
	depths := make(map[string]int)
	depths[root] = 0

	queue := []string{root}
	visited := make(map[string]bool)

	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]

		if visited[cur] {
			continue
		}
		visited[cur] = true

		node := g.Nodes[cur]
		if node == nil {
			continue
		}

		curDepth := depths[cur]
		deps := make([]string, len(node.Deps))
		copy(deps, node.Deps)
		sort.Strings(deps)

		for _, dep := range deps {
			if _, ok := depths[dep]; !ok {
				depths[dep] = curDepth + 1
			}
			if !visited[dep] {
				queue = append(queue, dep)
			}
		}
	}

	return depths
}

// buildDisplayLines builds the plain text display lines for the tree
func buildDisplayLines(g *Graph, entrypoint string) []displayLine {
	var lines []displayLine
	visited := make(map[string]bool)

	renderNode(g, entrypoint, nil, true, &lines, visited)
	return lines
}

// renderNode recursively renders a node and its children
func renderNode(g *Graph, path string, parentPipes []bool, isLast bool, lines *[]displayLine, visited map[string]bool) {
	node := g.Nodes[path]
	if node == nil {
		return
	}

	// Build prefix from parent pipes
	var prefix strings.Builder
	for _, pipe := range parentPipes {
		if pipe {
			prefix.WriteString("  ") // parent was last: no pipe
		} else {
			prefix.WriteString("│ ") // parent was not last: continue pipe
		}
	}

	isRoot := len(parentPipes) == 0

	// Build connector
	var connector string
	if isRoot {
		connector = ""
	} else if isLast {
		connector = "└"
	} else {
		connector = "├"
	}

	// Determine if this node has children (will be rendered)
	hasChildren := !visited[path] && len(node.Deps) > 0

	// Arrow indicator
	arrow := ""
	if !isRoot && hasChildren {
		arrow = "▷"
	} else if !isRoot {
		arrow = "▷"
	}

	lineText := prefix.String() + connector + arrow + node.RelPath
	if isRoot {
		lineText = node.RelPath
	}

	*lines = append(*lines, displayLine{
		text:     lineText,
		nodePath: path,
		isNode:   true,
	})

	if visited[path] {
		return
	}
	visited[path] = true

	if len(node.Deps) == 0 {
		return
	}

	// Sort and partition children
	deps := make([]string, len(node.Deps))
	copy(deps, node.Deps)
	sort.Strings(deps)

	// For multi-parent nodes: they appear at the end
	// Count parents for all reachable nodes
	// For now, don't partition - just render in alphabetical order
	// TODO: implement proper shared-node-last ordering

	// Add connector for children
	var childPipe strings.Builder
	for _, pipe := range parentPipes {
		if pipe {
			childPipe.WriteString("  ")
		} else {
			childPipe.WriteString("│ ")
		}
	}
	if isRoot {
		// Root: just │
	} else if isLast {
		childPipe.WriteString("  ")
	} else {
		childPipe.WriteString("│ ")
	}
	childPipeStr := childPipe.String()
	if isRoot {
		childPipeStr = ""
	}

	*lines = append(*lines, displayLine{
		text:     childPipeStr + "│",
		nodePath: path,
		isNode:   false,
	})

	// Render children
	newParentPipes := append(parentPipes, isLast)
	for i, child := range deps {
		renderNode(g, child, newParentPipes, i == len(deps)-1, lines, visited)
	}
}

// Terminal raw mode
type termState struct {
	termios syscall.Termios
}

const (
	_TCGETS = 0x5401
	_TCSETS = 0x5402
)

func makeRaw() (*termState, error) {
	state := &termState{}

	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL,
		uintptr(syscall.Stdin),
		_TCGETS,
		uintptr(unsafe.Pointer(&state.termios)))
	if errno != 0 {
		return nil, errno
	}

	raw := state.termios
	raw.Iflag &^= syscall.IGNBRK | syscall.BRKINT | syscall.PARMRK | syscall.ISTRIP | syscall.INLCR | syscall.IGNCR | syscall.ICRNL | syscall.IXON
	raw.Oflag &^= syscall.OPOST
	raw.Cflag &^= syscall.CSIZE | syscall.PARENB
	raw.Cflag |= syscall.CS8
	raw.Lflag &^= syscall.ECHO | syscall.ECHONL | syscall.ICANON | syscall.ISIG | syscall.IEXTEN
	raw.Cc[syscall.VMIN] = 1
	raw.Cc[syscall.VTIME] = 0

	_, _, errno = syscall.Syscall(syscall.SYS_IOCTL,
		uintptr(syscall.Stdin),
		_TCSETS,
		uintptr(unsafe.Pointer(&raw)))
	if errno != 0 {
		return nil, errno
	}

	return state, nil
}

func restoreTerminal(state *termState) {
	if state != nil {
		syscall.Syscall(syscall.SYS_IOCTL,
			uintptr(syscall.Stdin),
			_TCSETS,
			uintptr(unsafe.Pointer(&state.termios)))
	}
}

// computeParentCounts counts the number of parents for each node
func computeParentCounts(g *Graph, root string) map[string]int {
	counts := make(map[string]int)
	visited := make(map[string]bool)

	var dfs func(path string)
	dfs = func(path string) {
		if visited[path] {
			return
		}
		visited[path] = true

		node := g.Nodes[path]
		if node == nil {
			return
		}

		for _, dep := range node.Deps {
			counts[dep]++
			dfs(dep)
		}
	}

	dfs(root)
	return counts
}

// Suppress unused warnings
var _ = filepath.Base
var _ = sort.Strings
