		arrow = "▷"
	}

	lineText := prefix.String() + connector + arrow + node.RelPath
	if isRoot {
		lineText = node.RelPath
	}

	*lines = append(*lines, displayLine{
		text:     lineText,
		nodePath: path,
		isNode:   true,
