	entrypoint   string
	result       *TreeResult
	bfsOrder     []string // nodes in BFS order
	navStates    []string // navigation states (paths or "" for unselected)
	cursor       int      // current position in navStates
	lines        []displayLine
	scrollOffset int
	width        int
	height       int
}

func runTreeTUI(g *Graph, entrypoint string, result *TreeResult) error {
	width, height := getTerminalSize()

	tv := &treeViewState{
		g:          g,
		entrypoint: entrypoint,
		result:     result,
		width:      width,
		height:     height,
	}

	tv.bfsOrder = buildBFSOrder(g, entrypoint)
