package main

import (
	"bytes"
	"encoding/json"
	"fmt"
	"os"
	"sort"
	"strings"
)

// orderedMap is a map that serializes keys in sorted order  
type orderedMap map[string]interface{}

func (om orderedMap) MarshalJSON() ([]byte, error) {
	if om == nil {
		return []byte("null"), nil
	}
	keys := make([]string, 0, len(om))
	for k := range om {
		keys = append(keys, k)
	}
	sort.Strings(keys)

	var buf bytes.Buffer
	buf.WriteByte('{')
	for i, k := range keys {
		if i > 0 {
			buf.WriteByte(',')
		}
		kb, _ := json.Marshal(k)
		buf.Write(kb)
		buf.WriteByte(':')
		vb, err := marshalAny(om[k])
		if err != nil {
			return nil, err
		}
		buf.Write(vb)
	}
	buf.WriteByte('}')
	return buf.Bytes(), nil
}

func marshalAny(v interface{}) ([]byte, error) {
	if v == nil {
		return []byte("null"), nil
	}
	switch val := v.(type) {
	case orderedMap:
		return val.MarshalJSON()
	default:
		return json.Marshal(v)
	}
}

// printTreeJSON outputs the TreeResult as formatted JSON
func printTreeJSON(result *TreeResult) {
	var buf bytes.Buffer
	buf.WriteString("{\n")

	// tree
	buf.WriteString("  \"tree\": ")
	treeBytes := marshalTreeIndented(result.Tree, 2)
	buf.Write(treeBytes)
	buf.WriteString(",\n")

	// circularDependencies
	buf.WriteString("  \"circularDependencies\": ")
	circBytes := marshalCircularDeps(result.CircularDeps)
	buf.Write(circBytes)
	buf.WriteString(",\n")

	// errors
	buf.WriteString("  \"errors\": ")
	errBytes := marshalErrorsMap(result.Errors, 2)
	buf.Write(errBytes)
	buf.WriteString("\n}")

	fmt.Fprintln(os.Stdout, buf.String())
}

func marshalTreeIndented(v interface{}, depth int) []byte {
	if v == nil {
		return []byte("null")
	}
	om, ok := v.(orderedMap)
	if !ok {
		b, _ := json.Marshal(v)
		return b
	}
	if len(om) == 0 {
		return []byte("{}")
	}

	keys := make([]string, 0, len(om))
	for k := range om {
		keys = append(keys, k)
	}
	sort.Strings(keys)

	indent := strings.Repeat(" ", depth)
	innerIndent := strings.Repeat(" ", depth+2)

	var buf bytes.Buffer
	buf.WriteString("{\n")
	for i, k := range keys {
		buf.WriteString(innerIndent)
		kb, _ := json.Marshal(k)
		buf.Write(kb)
		buf.WriteString(": ")
		vb := marshalTreeIndented(om[k], depth+2)
		buf.Write(vb)
		if i < len(keys)-1 {
			buf.WriteByte(',')
		}
		buf.WriteByte('\n')
	}
	buf.WriteString(indent)
	buf.WriteByte('}')
	return buf.Bytes()
}

func marshalCircularDeps(deps [][]string) []byte {
	if len(deps) == 0 {
		return []byte("[]")
	}

	var buf bytes.Buffer
	buf.WriteString("[\n")
	for i, cycle := range deps {
		buf.WriteString("    [\n")
		for j, node := range cycle {
			buf.WriteString("      ")
			nb, _ := json.Marshal(node)
			buf.Write(nb)
			if j < len(cycle)-1 {
				buf.WriteByte(',')
