		return nil, err
	}

	return cfg, nil
}

// yamlLine represents a parsed YAML line
type yamlLine struct {
	indent  int
	content string // trimmed content
	isList  bool   // starts with "- "
	key     string
	value   string
	isKey   bool   // has a colon (key: value or key:)
}

func parseYAMLLines(data string) []yamlLine {
	var result []yamlLine
	for _, line := range strings.Split(data, "\n") {
		if strings.TrimSpace(line) == "" {
			continue
		}
		// Skip comments
		trimmed := strings.TrimLeft(line, " \t")
		if strings.HasPrefix(trimmed, "#") {
			continue
		}

		indent := countIndent(line)
		content := strings.TrimSpace(line)

		yl := yamlLine{indent: indent, content: content}

		if strings.HasPrefix(content, "- ") {
			yl.isList = true
			yl.content = strings.TrimPrefix(content, "- ")
		} else if content == "-" {
			yl.isList = true
			yl.content = ""
		}

		// Check if it has a colon
		if !yl.isList {
			if idx := strings.Index(yl.content, ":"); idx >= 0 {
				yl.isKey = true
				yl.key = unquoteYAML(strings.TrimSpace(yl.content[:idx]))
				yl.value = unquoteYAML(strings.TrimSpace(yl.content[idx+1:]))
			}
		} else {
			// List item might have inline key: value
			if idx := strings.Index(yl.content, ":"); idx >= 0 {
				possibleKey := strings.TrimSpace(yl.content[:idx])
				// Check if it looks like a key (no spaces, valid identifier chars)
				if !strings.Contains(possibleKey, " ") {
					yl.isKey = true
					yl.key = unquoteYAML(possibleKey)
					yl.value = unquoteYAML(strings.TrimSpace(yl.content[idx+1:]))
				}
			}
		}

		result = append(result, yl)
	}
	return result
}

func countIndent(line string) int {
	n := 0
	for _, c := range line {
		if c == ' ' {
			n++
		} else if c == '\t' {
			n += 2
		} else {
			break
		}
	}
	return n
}

// parseYAMLConfig parses the YAML config
func parseYAMLConfig(data string, cfg *Config) error {
	lines := parseYAMLLines(data)

	i := 0
	for i < len(lines) {
		line := lines[i]

		if line.indent != 0 || !line.isKey {
			i++
			continue
		}

		switch line.key {
		case "exclude":
			i++
			for i < len(lines) && lines[i].indent > 0 && lines[i].isList {
				cfg.Exclude = append(cfg.Exclude, unquoteYAML(lines[i].content))
				i++
			}
		case "only":
			i++
			for i < len(lines) && lines[i].indent > 0 && lines[i].isList {
				cfg.Only = append(cfg.Only, unquoteYAML(lines[i].content))
				i++
			}
		case "unwrapExports":
			cfg.UnwrapExports = parseBoolYAML(line.value)
			i++
		case "check":
			i++
			i = parseCheckConfig(lines, i, cfg)
		case "js":
			i++
			i = parseJSConfig(lines, i, cfg)
		case "python":
			i++
			i = parsePythonConfig(lines, i, cfg)
		case "rust":
			i++ // skip
			for i < len(lines) && lines[i].indent > 0 {
				i++
			}
		default:
			i++
		}
	}

	return nil
}

func parseCheckConfig(lines []yamlLine, start int, cfg *Config) int {
	i := start
	for i < len(lines) {
		line := lines[i]

		if line.indent < 2 {
			break
		}

		if line.indent == 2 && line.isKey {
			switch line.key {
			case "entrypoints":
				i++
				for i < len(lines) && lines[i].indent >= 4 && lines[i].isList {
					cfg.Check.Entrypoints = append(cfg.Check.Entrypoints, unquoteYAML(lines[i].content))
					i++
				}
			case "allowCircularDependencies":
				cfg.Check.AllowCircularDependencies = parseBoolYAML(line.value)
				i++
			case "allow":
				i++
				i = parseAllowConfig(lines, i, cfg)
			case "deny":
				i++
				i = parseDenyConfig(lines, i, cfg)
			case "aliases":
				i++
				i = parseAliasesConfig(lines, i, cfg)
			default:
				i++
			}
		} else {
			i++
		}
	}
	return i
}

func parseAllowConfig(lines []yamlLine, start int, cfg *Config) int {
	i := start
	for i < len(lines) {
		line := lines[i]

		if line.indent < 4 {
			break
		}

		if line.indent == 4 && line.isKey {
			pattern := line.key
			i++

			// Check what follows: list of patterns OR object with 'to' and 'reason'
			if cfg.Check.Allow == nil {
				cfg.Check.Allow = make(map[string]AllowRule)
			}

			rule := cfg.Check.Allow[pattern]

			// Read list items or sub-keys
			for i < len(lines) && lines[i].indent >= 6 {
				subLine := lines[i]
				if subLine.isList {
					rule.Patterns = append(rule.Patterns, unquoteYAML(subLine.content))
					i++
				} else if subLine.isKey {
					switch subLine.key {
					case "to":
						i++
						// Read list under 'to'
						for i < len(lines) && lines[i].indent >= 8 && lines[i].isList {
							rule.Patterns = append(rule.Patterns, unquoteYAML(lines[i].content))
							i++
						}
					case "reason":
						rule.Reason = subLine.value
						i++
					default:
						i++
					}
				} else {
					i++
				}
			}

			cfg.Check.Allow[pattern] = rule
		} else {
			i++
		}
	}
	return i
}

func parseDenyConfig(lines []yamlLine, start int, cfg *Config) int {
	i := start
	for i < len(lines) {
		line := lines[i]

		if line.indent < 4 {
			break
		}

		if line.indent == 4 && line.isKey {
			pattern := line.key
			i++

			if cfg.Check.Deny == nil {
				cfg.Check.Deny = make(map[string][]DenyItem)
			}

			// Read list items
			for i < len(lines) && lines[i].indent >= 6 {
				subLine := lines[i]
				if subLine.isList {
					if subLine.isKey && subLine.key == "to" {
						// - to: pattern [reason: ...]
						item := DenyItem{To: subLine.value}
						i++
						// Check for inline reason on next line
						for i < len(lines) && lines[i].indent >= 8 && !lines[i].isList {
							if lines[i].isKey && lines[i].key == "reason" {
								item.Reason = lines[i].value
							}
							i++
						}
						cfg.Check.Deny[pattern] = append(cfg.Check.Deny[pattern], item)
					} else {
						// Simple string pattern
						cfg.Check.Deny[pattern] = append(cfg.Check.Deny[pattern], DenyItem{To: unquoteYAML(subLine.content)})
						i++
					}
				} else {
					i++
				}
			}
		} else {
			i++
		}
	}
	return i
}

func parseAliasesConfig(lines []yamlLine, start int, cfg *Config) int {
	i := start
	for i < len(lines) {
		line := lines[i]

		if line.indent < 4 {
			break
		}

		if line.indent == 4 && line.isKey {
			aliasName := line.key
			i++

			if cfg.Check.Aliases == nil {
				cfg.Check.Aliases = make(map[string][]string)
			}

			for i < len(lines) && lines[i].indent >= 6 && lines[i].isList {
				cfg.Check.Aliases[aliasName] = append(cfg.Check.Aliases[aliasName], unquoteYAML(lines[i].content))
				i++
			}
		} else {
			i++
		}
	}
	return i
}

func parseJSConfig(lines []yamlLine, start int, cfg *Config) int {
	i := start
	for i < len(lines) {
		line := lines[i]
		if line.indent < 2 {
			break
		}
