// buildNavStates builds the navigation state sequence
func buildNavStates(g *Graph, entrypoint string, bfsOrder []string) []string {
	if len(bfsOrder) == 0 {
		return []string{""}
	}

	var states []string
	states = append(states, bfsOrder[0]) // root

	if len(bfsOrder) == 1 {
		return states
	}

	states = append(states, "") // transition after root

	depths := computeNodeDepths(g, entrypoint)
	prevDepth := 0

	for i := 1; i < len(bfsOrder); i++ {
		node := bfsOrder[i]
		curDepth := depths[node]

		if curDepth > prevDepth && i > 1 {
			states = append(states, "") // transition when going deeper
		}

		states = append(states, node)
		prevDepth = curDepth
	}

	return states
}

func computeNodeDepths(g *Graph, root string) map[string]int {
	depths := make(map[string]int)
	depths[root] = 0

	queue := []string{root}
	visited := make(map[string]bool)

	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]

		if visited[cur] {
			continue
		}
		visited[cur] = true

		n := g.Nodes[cur]
		if n == nil {
			continue
		}

		curDepth := depths[cur]
		for _, dep := range n.Deps {
			if _, ok := depths[dep]; !ok {
				depths[dep] = curDepth + 1
			}
			if !visited[dep] {
				queue = append(queue, dep)
			}
		}
	}

	return depths
}

// buildDisplayLines builds the tree display lines
func buildDisplayLines(g *Graph, entrypoint string) []displayLine {
	var lines []displayLine
	visited := make(map[string]bool)
	renderNode(g, entrypoint, nil, true, &lines, visited)
	return lines
}

func renderNode(g *Graph, path string, parentPipes []bool, isLast bool, lines *[]displayLine, visited map[string]bool) {
	node := g.Nodes[path]
	if node == nil {
		return
	}

	var prefix strings.Builder
	for _, pipe := range parentPipes {
		if pipe {
			prefix.WriteString("  ")
		} else {
			prefix.WriteString("│ ")
		}
	}

	isRoot := len(parentPipes) == 0

	var connector string
	if !isRoot {
		if isLast {
			connector = "└"
		} else {
			connector = "├"
		}
	}

	arrow := ""
	if !isRoot {
		arrow = "▷"
	}

	var lineText string
	if isRoot {
		lineText = node.RelPath
	} else {
		lineText = prefix.String() + connector + arrow + node.RelPath
	}

	*lines = append(*lines, displayLine{
		text:     lineText,
		nodePath: path,
		isNode:   true,
	})

	if visited[path] {
		return
	}
	visited[path] = true

	if len(node.Deps) == 0 {
		return
	}

	deps := make([]string, len(node.Deps))
	copy(deps, node.Deps)
	sort.Strings(deps)

	// Add connector line
	var childPipe strings.Builder
	for _, pipe := range parentPipes {
		if pipe {
			childPipe.WriteString("  ")
		} else {
			childPipe.WriteString("│ ")
		}
	}
	if !isRoot {
		if isLast {
			childPipe.WriteString("  ")
		} else {
			childPipe.WriteString("│ ")
		}
	}

	*lines = append(*lines, displayLine{
		text:     childPipe.String() + "│",
		nodePath: path,
		isNode:   false,
	})

	newPipes := append(parentPipes, isLast)
	for i, child := range deps {
		renderNode(g, child, newPipes, i == len(deps)-1, lines, visited)
	}
}

// computeParentCounts counts parents for each node
func computeParentCounts(g *Graph, root string) map[string]int {
	counts := make(map[string]int)
	visited := make(map[string]bool)

	var dfs func(path string)
	dfs = func(path string) {
		if visited[path] {
			return
		}
		visited[path] = true
		n := g.Nodes[path]
		if n == nil {
			return
		}
		for _, dep := range n.Deps {
			counts[dep]++
			dfs(dep)
		}
	}
	dfs(root)
	return counts
}

// Terminal raw mode
type termState struct {
	termios syscall.Termios
}

const (
	_TCGETS = 0x5401
	_TCSETS = 0x5402
)

func makeRaw() (*termState, error) {
	state := &termState{}

	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL,
		uintptr(syscall.Stdin),
		_TCGETS,
		uintptr(unsafe.Pointer(&state.termios)))
	if errno != 0 {
		return nil, errno
	}

	raw := state.termios
	raw.Iflag &^= syscall.IGNBRK | syscall.BRKINT | syscall.PARMRK | syscall.ISTRIP | syscall.INLCR | syscall.IGNCR | syscall.ICRNL | syscall.IXON
	raw.Oflag &^= syscall.OPOST
	raw.Cflag &^= syscall.CSIZE | syscall.PARENB
	raw.Cflag |= syscall.CS8
	raw.Lflag &^= syscall.ECHO | syscall.ECHONL | syscall.ICANON | syscall.ISIG | syscall.IEXTEN
	raw.Cc[syscall.VMIN] = 1
	raw.Cc[syscall.VTIME] = 0

	_, _, errno = syscall.Syscall(syscall.SYS_IOCTL,
		uintptr(syscall.Stdin),
		_TCSETS,
		uintptr(unsafe.Pointer(&raw)))
	if errno != 0 {
		return nil, errno
	}

	return state, nil
}

func restoreTerminal(state *termState) {
	if state != nil {
		syscall.Syscall(syscall.SYS_IOCTL,
			uintptr(syscall.Stdin),
			_TCSETS,
			uintptr(unsafe.Pointer(&state.termios)))
	}
}

