package main

import (
	"bufio"
	"fmt"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"syscall"
	"unicode/utf8"
	"unsafe"
)

// ANSI color codes
const (
	colorReset   = "\x1b[39m"
	colorGreen   = "\x1b[32m"
	colorCyan    = "\x1b[36m"
	colorMagenta = "\x1b[35m"
	colorRed     = "\x1b[31m"
)

// getTerminalSize returns terminal dimensions
func getTerminalSize() (width, height int) {
	type winsize struct {
		Row    uint16
		Col    uint16
		Xpixel uint16
		Ypixel uint16
	}
	ws := &winsize{}
	retCode, _, _ := syscall.Syscall(syscall.SYS_IOCTL,
		uintptr(syscall.Stdout),
		uintptr(syscall.TIOCGWINSZ),
		uintptr(unsafe.Pointer(ws)))
	if retCode == 0 {
		return int(ws.Col), int(ws.Row)
	}
