}

// displayLine represents a rendered tree line
type displayLine struct {
	text     string // plain text (no ANSI)
	nodePath string // absolute path of the node
	isNode   bool   // is this a node line (vs connector)
}

// treeViewState is the TUI state
type treeViewState struct {
	g          *Graph
	entrypoint string
	result     *TreeResult
	bfsOrder   []string
	navStates  []string  // navigation states (path or "" for unselected)
	cursor     int
	lines      []displayLine
	scrollOffset int
	width      int
	height     int
	prevLines  int // number of lines rendered last time
}

func runTreeTUI(g *Graph, entrypoint string, result *TreeResult) error {
	width, height := getTerminalSize()

	tv := &treeViewState{
		g:          g,
		entrypoint: entrypoint,
		result:     result,
		width:      width,
		height:     height,
	}

	tv.bfsOrder = buildBFSOrder(g, entrypoint)
	tv.navStates = buildNavStates(g, entrypoint, tv.bfsOrder)
	tv.lines = buildDisplayLines(g, entrypoint)
	tv.cursor = 0

	// Set up raw terminal
	oldState, err := makeRaw()
	if err != nil {
		return fmt.Errorf("exit status 1")
	}
	defer restoreTerminal(oldState)

	// Hide cursor
	fmt.Print("\x1b[?25l")
	defer fmt.Print("\x1b[?25h")

	// Initial render
	tv.renderAll()

	reader := bufio.NewReader(os.Stdin)
	for {
		b, err := reader.ReadByte()
		if err != nil {
			break
		}

		switch b {
		case 'q', 3: // q or Ctrl+C
			// Clear rendered content
			tv.clearRendered()
			return nil
		case 27: // ESC sequence
			b2, err2 := reader.ReadByte()
			if err2 != nil || b2 != '[' {
				continue
			}
			b3, err3 := reader.ReadByte()
			if err3 != nil {
				continue
			}
			switch b3 {
			case 'A': // Up arrow
				tv.moveCursor(-1)
				tv.renderAll()
			case 'B': // Down arrow
				tv.moveCursor(1)
				tv.renderAll()
			}
		}
	}

	return nil
}

func (tv *treeViewState) clearRendered() {
	if tv.prevLines > 0 {
		// Go up prevLines and clear
		fmt.Printf("\x1b[%dA\x1b[0J", tv.prevLines)
	}
}

func (tv *treeViewState) moveCursor(delta int) {
	n := len(tv.navStates)
	tv.cursor += delta
	if tv.cursor < 0 {
		tv.cursor = 0
	}
	if tv.cursor >= n {
		tv.cursor = n - 1
	}
	tv.updateScroll()
}

func (tv *treeViewState) updateScroll() {
	selectedPath := ""
	if tv.cursor < len(tv.navStates) {
		selectedPath = tv.navStates[tv.cursor]
	}
	if selectedPath == "" {
		return
	}

	for i, line := range tv.lines {
		if line.isNode && line.nodePath == selectedPath {
			if i < tv.scrollOffset {
				tv.scrollOffset = i
			}
			if i >= tv.scrollOffset+tv.height {
				tv.scrollOffset = i - tv.height + 1
			}
			return
		}
	}
}

// renderAll renders the full tree view
func (tv *treeViewState) renderAll() {
	// Go back to start of previous render
	if tv.prevLines > 0 {
		fmt.Printf("\x1b[%dA", tv.prevLines)
	}

	selectedPath := ""
	isUnselected := true
	if tv.cursor < len(tv.navStates) {
		selectedPath = tv.navStates[tv.cursor]
		isUnselected = (selectedPath == "")
	}

	leftWidth := tv.width - 40
	if leftWidth < 10 {
		leftWidth = 10
	}

	// Get errors for selected node
	var selectedErrors []string
	if !isUnselected && selectedPath != "" {
		if node, ok := tv.g.Nodes[selectedPath]; ok {
			if errs, ok := tv.result.Errors[node.RelPath]; ok {
				selectedErrors = errs
			} else if len(node.Errors) > 0 {
				selectedErrors = node.Errors
			}
		}
	}

	errDisplayLines := computeErrorLines(selectedErrors)

	startLine := tv.scrollOffset
	if startLine < 0 {
		startLine = 0
	}

	linesRendered := 0
	for i := 0; i < tv.height; i++ {
		lineIdx := startLine + i

		var treePart string
		if lineIdx < len(tv.lines) {
			treePart = tv.colorTreeLine(tv.lines[lineIdx], selectedPath, isUnselected)
		}

		// Pad tree part to leftWidth
		plainLen := visibleLen(treePart)
		if plainLen < leftWidth {
			treePart += strings.Repeat(" ", leftWidth-plainLen)
		} else if plainLen > leftWidth {
			// Truncate
			treePart = truncateToWidth(treePart, leftWidth)
		}

		var errPart string
		if i < len(errDisplayLines) {
			errPart = errDisplayLines[i]
		}

		line := treePart + errPart
		fmt.Print(line + "\x1b[0K\n")
		linesRendered++
	}

	tv.prevLines = linesRendered
}

func truncateToWidth(s string, maxWidth int) string {
	stripped := stripAnsi(s)
	if visibleLen(stripped) <= maxWidth {
		return s
	}
	// Find where to cut in the original string
	// This is approximate
	count := 0
	i := 0
	for i < len(s) {
		if s[i] == '\x1b' {
			// Skip ANSI sequence
			for i < len(s) && s[i] != 'm' {
				i++
			}
			i++
			continue
		}
		_, size := utf8.DecodeRuneInString(s[i:])
		count++
		if count > maxWidth {
			return s[:i]
		}
		i += size
	}
	return s
}

// colorTreeLine applies color to a tree line
func (tv *treeViewState) colorTreeLine(line displayLine, selectedPath string, isUnselected bool) string {
	nodeName := ""
	if line.nodePath != "" {
		if node, ok := tv.g.Nodes[line.nodePath]; ok {
			nodeName = node.RelPath
		}
	}

	hasErrors := false
	if line.nodePath != "" {
		if node, ok := tv.g.Nodes[line.nodePath]; ok {
			if len(node.Errors) > 0 {
				hasErrors = true
			}
			if errs, ok := tv.result.Errors[node.RelPath]; ok && len(errs) > 0 {
				hasErrors = true
			}
		}
	}

	if !line.isNode {
		// Connector line - color if part of selected path
		if !isUnselected && selectedPath != "" {
			// Check if this connector line belongs to the selected path
			if isOnSelectedPathTree(line.nodePath, selectedPath, tv.g, tv.result) {
				return colorGreen + line.text + colorReset
			}
		}
		return line.text
	}

	// Extract prefix (box-drawing chars) and name
	prefix := extractBoxPrefix(line.text)

	if line.nodePath == selectedPath && !isUnselected {
		if hasErrors {
			return prefix + colorMagenta + nodeName + colorReset
		}
		return prefix + colorGreen + nodeName + colorReset
	}

	if isUnselected {
		if hasErrors {
			return prefix + colorRed + nodeName + colorReset
		}
		return line.text
	}

	// Another node when something is selected
	// Check if this node is in the selected path's subtree
	if isOnSelectedPathTree(line.nodePath, selectedPath, tv.g, tv.result) {
		if hasErrors {
			return prefix + colorCyan + nodeName + colorReset
		}
		return prefix + colorCyan + nodeName + colorReset
	}

	if hasErrors {
		return prefix + colorRed + nodeName + colorReset
	}
	return line.text
}

// isOnSelectedPathTree checks if a node is the selected node or has selected node as ancestor
func isOnSelectedPathTree(nodePath, selectedPath string, g *Graph, result *TreeResult) bool {
	if nodePath == "" || selectedPath == "" {
		return false
	}
	if nodePath == selectedPath {
		return true
	}
	// Check if selectedPath is reachable from nodePath
	visited := make(map[string]bool)
	queue := []string{nodePath}
	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]
		if cur == selectedPath {
			return true
		}
		if visited[cur] {
			continue
		}
		visited[cur] = true
		n := g.Nodes[cur]
		if n != nil {
			for _, dep := range n.Deps {
				queue = append(queue, dep)
			}
		}
	}
	return false
}

func extractBoxPrefix(line string) string {
	i := 0
	runes := []rune(line)
	for i < len(runes) {
		r := runes[i]
		if !isBoxDrawingChar(r) && r != ' ' {
			break
		}
		i++
	}
	return string(runes[:i])
}

func isBoxDrawingChar(r rune) bool {
	return r == '│' || r == '├' || r == '└' || r == '─' || r == '▷' || r == '┴' || r == '╷'
}

// computeErrorLines formats errors for display
func computeErrorLines(errors []string) []string {
	if len(errors) == 0 {
		return nil
	}

	var lines []string
	for _, errMsg := range errors {
		// Wrap at 36 chars per line
		wrapped := wordWrap(errMsg, 36)
		for j, wline := range wrapped {
			if j == 0 {
				lines = append(lines, colorRed+"- "+wline+colorReset)
			} else {
				lines = append(lines, colorRed+wline+colorReset)
			}
		}
	}

	return lines
}

func wordWrap(text string, maxWidth int) []string {
	if maxWidth <= 0 {
		return []string{text}
	}
	words := strings.Fields(text)
	var lines []string
	var current strings.Builder

	for _, word := range words {
		if current.Len() == 0 {
			current.WriteString(word)
		} else if current.Len()+1+len(word) <= maxWidth {
			current.WriteString(" ")
			current.WriteString(word)
		} else {
			lines = append(lines, current.String())
			current.Reset()
			current.WriteString(word)
		}
	}
	if current.Len() > 0 {
		lines = append(lines, current.String())
	}
	if len(lines) == 0 {
		return []string{""}
	}
	return lines
}

func visibleLen(s string) int {
	count := 0
	i := 0
	for i < len(s) {
		if s[i] == '\x1b' {
			for i < len(s) && s[i] != 'm' {
				i++
			}
			i++
			continue
		}
		_, size := utf8.DecodeRuneInString(s[i:])
		count++
		i += size
	}
	return count
}

func stripAnsi(s string) string {
	var result strings.Builder
	i := 0
	for i < len(s) {
		if s[i] == '\x1b' {
			for i < len(s) && s[i] != 'm' {
				i++
			}
			i++
			continue
		}
		_, size := utf8.DecodeRuneInString(s[i:])
		result.WriteString(s[i : i+size])
		i += size
	}
	return result.String()
}

// buildNavStates builds the navigation state sequence
func buildNavStates(g *Graph, entrypoint string, bfsOrder []string) []string {
	if len(bfsOrder) == 0 {
		return []string{""}
	}

	var states []string
	states = append(states, bfsOrder[0]) // root

	if len(bfsOrder) == 1 {
		return states
	}

	states = append(states, "") // transition after root

	depths := computeNodeDepths(g, entrypoint)
	prevDepth := 0

	for i := 1; i < len(bfsOrder); i++ {
		node := bfsOrder[i]
		curDepth := depths[node]

		if curDepth > prevDepth && i > 1 {
			states = append(states, "") // transition when going deeper
		}

		states = append(states, node)
		prevDepth = curDepth
	}

	return states
}

