func truncateToWidth(s string, maxWidth int) string {
	stripped := stripAnsi(s)
	if visibleLen(stripped) <= maxWidth {
		return s
	}
	// Find where to cut in the original string
	// This is approximate
	count := 0
	i := 0
	for i < len(s) {
		if s[i] == '\x1b' {
			// Skip ANSI sequence
			for i < len(s) && s[i] != 'm' {
				i++
			}
			i++
			continue
		}
		_, size := utf8.DecodeRuneInString(s[i:])
		count++
		if count > maxWidth {
			return s[:i]
		}
		i += size
	}
	return s
}

// colorTreeLine applies color to a tree line
func (tv *treeViewState) colorTreeLine(line displayLine, selectedPath string, isUnselected bool) string {
	nodeName := ""
	if line.nodePath != "" {
		if node, ok := tv.g.Nodes[line.nodePath]; ok {
			nodeName = node.RelPath
		}
	}

	hasErrors := false
	if line.nodePath != "" {
		if node, ok := tv.g.Nodes[line.nodePath]; ok {
			if len(node.Errors) > 0 {
				hasErrors = true
			}
			if errs, ok := tv.result.Errors[node.RelPath]; ok && len(errs) > 0 {
				hasErrors = true
			}
		}
	}

	if !line.isNode {
		// Connector line - color if part of selected path
		if !isUnselected && selectedPath != "" {
			// Check if this connector line belongs to the selected path
			if isOnSelectedPathTree(line.nodePath, selectedPath, tv.g, tv.result) {
				return colorGreen + line.text + colorReset
			}
		}
		return line.text
	}

	// Extract prefix (box-drawing chars) and name
	prefix := extractBoxPrefix(line.text)

	if line.nodePath == selectedPath && !isUnselected {
		if hasErrors {
			return prefix + colorMagenta + nodeName + colorReset
		}
		return prefix + colorGreen + nodeName + colorReset
	}

	if isUnselected {
		if hasErrors {
			return prefix + colorRed + nodeName + colorReset
		}
		return line.text
	}

	// Another node when something is selected
	// Check if this node is in the selected path's subtree
	if isOnSelectedPathTree(line.nodePath, selectedPath, tv.g, tv.result) {
		if hasErrors {
			return prefix + colorCyan + nodeName + colorReset
		}
		return prefix + colorCyan + nodeName + colorReset
	}

	if hasErrors {
		return prefix + colorRed + nodeName + colorReset
	}
	return line.text
}

// isOnSelectedPathTree checks if a node is the selected node or has selected node as ancestor
func isOnSelectedPathTree(nodePath, selectedPath string, g *Graph, result *TreeResult) bool {
	if nodePath == "" || selectedPath == "" {
		return false
	}
	if nodePath == selectedPath {
		return true
	}
	// Check if selectedPath is reachable from nodePath
	visited := make(map[string]bool)
	queue := []string{nodePath}
	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]
		if cur == selectedPath {
			return true
		}
		if visited[cur] {
			continue
		}
		visited[cur] = true
		n := g.Nodes[cur]
		if n != nil {
			for _, dep := range n.Deps {
				queue = append(queue, dep)
			}
		}
	}
	return false
}

func extractBoxPrefix(line string) string {
	i := 0
	runes := []rune(line)
	for i < len(runes) {
		r := runes[i]
		if !isBoxDrawingChar(r) && r != ' ' {
			break
		}
		i++
	}
	return string(runes[:i])
}

func isBoxDrawingChar(r rune) bool {
	return r == '│' || r == '├' || r == '└' || r == '─' || r == '▷' || r == '┴' || r == '╷'
}

// computeErrorLines formats errors for display
func computeErrorLines(errors []string) []string {
	if len(errors) == 0 {
		return nil
	}

	var lines []string
	for _, errMsg := range errors {
		// Wrap at 36 chars per line
		wrapped := wordWrap(errMsg, 36)
		for j, wline := range wrapped {
			if j == 0 {
				lines = append(lines, colorRed+"- "+wline+colorReset)
			} else {
				lines = append(lines, colorRed+wline+colorReset)
			}
		}
	}

	return lines
}

func wordWrap(text string, maxWidth int) []string {
	if maxWidth <= 0 {
		return []string{text}
	}
	words := strings.Fields(text)
	var lines []string
	var current strings.Builder

	for _, word := range words {
		if current.Len() == 0 {
			current.WriteString(word)
		} else if current.Len()+1+len(word) <= maxWidth {
			current.WriteString(" ")
			current.WriteString(word)
		} else {
			lines = append(lines, current.String())
			current.Reset()
			current.WriteString(word)
		}
	}
	if current.Len() > 0 {
		lines = append(lines, current.String())
	}
	if len(lines) == 0 {
		return []string{""}
	}
	return lines
}

func visibleLen(s string) int {
	count := 0
	i := 0
	for i < len(s) {
		if s[i] == '\x1b' {
			for i < len(s) && s[i] != 'm' {
				i++
			}
			i++
			continue
		}
		_, size := utf8.DecodeRuneInString(s[i:])
		count++
		i += size
	}
	return count
}

func stripAnsi(s string) string {
	var result strings.Builder
	i := 0
	for i < len(s) {
		if s[i] == '\x1b' {
			for i < len(s) && s[i] != 'm' {
				i++
			}
			i++
			continue
		}
		_, size := utf8.DecodeRuneInString(s[i:])
		result.WriteString(s[i : i+size])
		i += size
	}
	return result.String()
}

// buildNavStates builds the navigation state sequence
func buildNavStates(g *Graph, entrypoint string, bfsOrder []string) []string {
	if len(bfsOrder) == 0 {
		return []string{""}
	}

	var states []string
	states = append(states, bfsOrder[0]) // root

	if len(bfsOrder) == 1 {
		return states
	}

	states = append(states, "") // transition after root

	depths := computeNodeDepths(g, entrypoint)
	prevDepth := 0

	for i := 1; i < len(bfsOrder); i++ {
		node := bfsOrder[i]
		curDepth := depths[node]

		if curDepth > prevDepth && i > 1 {
			states = append(states, "") // transition when going deeper
		}

		states = append(states, node)
		prevDepth = curDepth
	}

	return states
}

func computeNodeDepths(g *Graph, root string) map[string]int {
	depths := make(map[string]int)
	depths[root] = 0

	queue := []string{root}
	visited := make(map[string]bool)

	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]

		if visited[cur] {
			continue
		}
		visited[cur] = true

		n := g.Nodes[cur]
		if n == nil {
			continue
		}

		curDepth := depths[cur]
		for _, dep := range n.Deps {
			if _, ok := depths[dep]; !ok {
				depths[dep] = curDepth + 1
			}
			if !visited[dep] {
				queue = append(queue, dep)
			}
		}
	}

	return depths
}

// buildDisplayLines builds the tree display lines
func buildDisplayLines(g *Graph, entrypoint string) []displayLine {
	var lines []displayLine
	visited := make(map[string]bool)
	renderNode(g, entrypoint, nil, true, &lines, visited)
	return lines
}

func renderNode(g *Graph, path string, parentPipes []bool, isLast bool, lines *[]displayLine, visited map[string]bool) {
	node := g.Nodes[path]
	if node == nil {
		return
	}

	var prefix strings.Builder
	for _, pipe := range parentPipes {
		if pipe {
			prefix.WriteString("  ")
		} else {
			prefix.WriteString("│ ")
		}
	}

	isRoot := len(parentPipes) == 0

	var connector string
	if !isRoot {
		if isLast {
			connector = "└"
		} else {
			connector = "├"
		}
	}

	arrow := ""
	if !isRoot {
		arrow = "▷"
	}

	var lineText string
	if isRoot {
		lineText = node.RelPath
	} else {
		lineText = prefix.String() + connector + arrow + node.RelPath
	}

	*lines = append(*lines, displayLine{
		text:     lineText,
		nodePath: path,
		isNode:   true,
	})

	if visited[path] {
		return
	}
	visited[path] = true

	if len(node.Deps) == 0 {
		return
	}

	deps := make([]string, len(node.Deps))
	copy(deps, node.Deps)
	sort.Strings(deps)

	// Add connector line
	var childPipe strings.Builder
	for _, pipe := range parentPipes {
		if pipe {
			childPipe.WriteString("  ")
		} else {
			childPipe.WriteString("│ ")
		}
	}
	if !isRoot {
		if isLast {
			childPipe.WriteString("  ")
		} else {
			childPipe.WriteString("│ ")
		}
	}

	*lines = append(*lines, displayLine{
		text:     childPipe.String() + "│",
		nodePath: path,
		isNode:   false,
	})

	newPipes := append(parentPipes, isLast)
	for i, child := range deps {
		renderNode(g, child, newPipes, i == len(deps)-1, lines, visited)
	}
}

// computeParentCounts counts parents for each node
func computeParentCounts(g *Graph, root string) map[string]int {
	counts := make(map[string]int)
	visited := make(map[string]bool)

	var dfs func(path string)
	dfs = func(path string) {
		if visited[path] {
			return
		}
		visited[path] = true
		n := g.Nodes[path]
		if n == nil {
			return
		}
		for _, dep := range n.Deps {
			counts[dep]++
			dfs(dep)
		}
	}
	dfs(root)
	return counts
}

// Terminal raw mode
type termState struct {
	termios syscall.Termios
}

const (
	_TCGETS = 0x5401
	_TCSETS = 0x5402
)

func makeRaw() (*termState, error) {
	state := &termState{}

	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL,
		uintptr(syscall.Stdin),
		_TCGETS,
		uintptr(unsafe.Pointer(&state.termios)))
	if errno != 0 {
		return nil, errno
	}

	raw := state.termios
	raw.Iflag &^= syscall.IGNBRK | syscall.BRKINT | syscall.PARMRK | syscall.ISTRIP | syscall.INLCR | syscall.IGNCR | syscall.ICRNL | syscall.IXON
	raw.Oflag &^= syscall.OPOST
	raw.Cflag &^= syscall.CSIZE | syscall.PARENB
	raw.Cflag |= syscall.CS8
	raw.Lflag &^= syscall.ECHO | syscall.ECHONL | syscall.ICANON | syscall.ISIG | syscall.IEXTEN
	raw.Cc[syscall.VMIN] = 1
	raw.Cc[syscall.VTIME] = 0

	_, _, errno = syscall.Syscall(syscall.SYS_IOCTL,
		uintptr(syscall.Stdin),
		_TCSETS,
		uintptr(unsafe.Pointer(&raw)))
	if errno != 0 {
		return nil, errno
	}

	return state, nil
}

func restoreTerminal(state *termState) {
	if state != nil {
		syscall.Syscall(syscall.SYS_IOCTL,
			uintptr(syscall.Stdin),
			_TCSETS,
			uintptr(unsafe.Pointer(&state.termios)))
	}
}

