// treeCell represents a single "column" in the tree display
type treeCell struct {
	hasChildren bool   // this parent has children that haven't been rendered yet
	parentPath  string // absolute path of the parent
}

// buildCorrectDisplayLines implements the original dep-tree rendering algorithm
// The key behavior: shared nodes are shown at the bottom with merged connectors
func buildCorrectDisplayLines(g *Graph, entrypoint string) []displayLine {
	// Pre-compute parent counts for all nodes
	parentCounts := computeParentCounts(g, entrypoint)

	var lines []displayLine
	visited := make(map[string]bool)

	// Render the tree starting from root
	renderCorrectNode(g, entrypoint, []treeCell{}, true, true, &lines, visited, parentCounts)

	return lines
}

// renderCorrectNode renders a node with the correct dep-tree algorithm
// cols: the "live" parent columns to the right of the current position
// isRoot: whether this is the root node
// isLast: whether this is the last child of its parent
func renderCorrectNode(g *Graph, path string, cols []treeCell, isLast bool, isRoot bool, lines *[]displayLine, visited map[string]bool, parentCounts map[string]int) {
	node := g.Nodes[path]
	if node == nil {
		return
	}

	if visited[path] {
		return
	}
	visited[path] = true

	// Build the prefix string from live columns
