		if col.hasChildren {
			prefix.WriteString("│")
		} else {
			prefix.WriteString(" ")
		}
	}

	var lineText string
	if isRoot {
		lineText = node.RelPath
	} else {
		// Build: connector + live pipes + name
		// But the layout is different - the connector comes FIRST, then pipes
		// Actually from the original:
		// "├▷a.ts" - connector then name
		// "├▷│b.ts" - connector then pipes then name
		// The pipes come BETWEEN connector and name but AFTER the connector

		// Rebuild more carefully:
		var sb strings.Builder
		if isLast {
			sb.WriteString("└▷")
		} else {
			sb.WriteString("├▷")
		}
		for _, col := range cols {
			if col.hasChildren {
				sb.WriteString("│")
			}
		}
		sb.WriteString(node.RelPath)
		lineText = sb.String()
	}

	*lines = append(*lines, displayLine{
		text:     lineText,
		nodePath: path,
		isNode:   true,
	})

	if len(node.Deps) == 0 {
		return
	}

	// Get and sort children
	deps := make([]string, len(node.Deps))
	copy(deps, node.Deps)
	sortAlpha(deps)

	// Partition children: non-shared first, shared last
	var nonShared, shared []string
	for _, dep := range deps {
		if parentCounts[dep] > 1 {
			shared = append(shared, dep)
		} else {
			nonShared = append(nonShared, dep)
		}
	}
	allChildren := append(nonShared, shared...)

	// For each child, render it with the appropriate cols
	// First, add a connector line "│" (or appropriate pipes)

	// Build connector line from current position
	var connPipe strings.Builder
	for _, col := range cols {
		if col.hasChildren {
			connPipe.WriteString("│ ")
		} else {
			connPipe.WriteString("  ")
		}
	}
	if !isRoot {
		if isLast {
			connPipe.WriteString("  ")
		} else {
			connPipe.WriteString("│ ")
		}
	}

	*lines = append(*lines, displayLine{
		text:     connPipe.String() + "│",
		nodePath: path,
		isNode:   false,
	})

	// Render each child
	// For child i: the "cols" include:
	// - All cols passed to current node (filtered by hasChildren)
	// - A col for the current node itself (hasChildren=true since we have deps)
	// - For each PREVIOUS sibling j < i: a col if sibling j has children in the "remaining" set
	//
	// Actually this gets complex. Let me use the simpler direct approach.
	//
	// For the root's children:
	// When rendering child i:
	// The "live columns" to the right of child i's connector are:
	//   - Previous siblings (0..i-1) that have children yet to be rendered
	//
	// Actually the CORRECT layout from the original is:
	// All children of a node are shown at the SAME "indent level"
	// Each child appears AFTER the previous child, adding a pipe for previous sibling if it has children
	//
	// For ROOT with children [a,b,c]:
	// a: "├▷a.ts" (no previous siblings with pipes)
	// b: "├▷│b.ts" (a has children, so one │)
	// c: "└▷││c.ts" (a and b both have children, so ││)
	// Then shared nodes (d) appear below with merged pipes

	// Build the "sibling context" - which previous siblings have children
	siblingPipes := make([]treeCell, 0) // live pipes from THIS level's previous siblings

	for i, child := range allChildren {
		childIsLast := i == len(allChildren)-1

		// Build the new cols for this child
		// = old cols (from grandparent) + current node's "continuation" + sibling pipes
		var childCols []treeCell

		// Parent's continuation columns
		for _, col := range cols {
			childCols = append(childCols, col)
		}
		// Current node's column (only if current node is not last AND we're not rendering root's children)
		if !isRoot && !isLast {
			childCols = append(childCols, treeCell{hasChildren: true, parentPath: path})
		}
		// Sibling pipes (from previous siblings at this level)
		childCols = append(childCols, siblingPipes...)

		// Render the child
		childNode := g.Nodes[child]
		if childNode == nil {
			continue
		}

		// Render child line
		var childLineText strings.Builder
		if childIsLast {
			childLineText.WriteString("└▷")
		} else {
			childLineText.WriteString("├▷")
		}
		// Add sibling pipes as column markers AFTER the connector
		for _, col := range siblingPipes {
			if col.hasChildren {
				childLineText.WriteString("│")
			}
		}
		childLineText.WriteString(childNode.RelPath)

		if !visited[child] {
			visited[child] = true
			*lines = append(*lines, displayLine{
				text:     childLineText.String(),
				nodePath: child,
				isNode:   true,
			})
		}

		// Check if this child has children (to know if we need pipes for it)
		childHasChildren := len(childNode.Deps) > 0

		// Recursively render child's subtree if needed
		// But NOT inline - we'll render children at the END after all siblings

		// Update sibling pipes for next siblings
		if childHasChildren {
			siblingPipes = append(siblingPipes, treeCell{hasChildren: true, parentPath: child})
		}
		_ = childCols
	}

	// Now render children's subtrees
	// The order: non-shared children's subtrees first, then shared
	// But all at the same "level" (no deeper indent for now)
	// Actually we just recurse normally - the children will be at a deeper level

	// For now, use the simple recursive approach
	// Rebuild for proper rendering
	_ = siblingPipes
}

func sortAlpha(ss []string) {
	for i := 0; i < len(ss); i++ {
		for j := i + 1; j < len(ss); j++ {
			if ss[i] > ss[j] {
				ss[i], ss[j] = ss[j], ss[i]
			}
		}
	}
}
